"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["6739"],{2095(e,i,o){o.r(i),o.d(i,{metadata:()=>n,default:()=>d,frontMatter:()=>t,contentTitle:()=>l,toc:()=>s});var n=JSON.parse('{"docId":"references/paper","permalink":"/it-IT/docs/references/paper","source":"@site/i18n/it-IT/lagune-docs-content/references/paper.mdx","title":"Security-Driven Hardening: una convenzione per l\'era dello sviluppo assistito dall\'IA","sidebarLabel":"Articolo sulla metodologia","description":"La metodologia Security-Driven Hardening (SDH): una convenzione blue team sensibile al contesto per verificare e mettere in sicurezza il software sviluppato con l\'aiuto dell\'IA o in vibe coding.","keywords":["Security-Driven Hardening","SDH","sicurezza difensiva","hardening","spec-driven development","articolo di Lagune"],"datePublished":"2026-11-03T17:46:13.000Z","dateModified":"2026-11-04T12:37:17.000Z","state":"translated","alternates":[{"locale":"en","permalink":"/docs/references/paper"},{"locale":"pt-BR","permalink":"/pt-BR/docs/references/paper"},{"locale":"es-ES","permalink":"/es-ES/docs/references/paper"},{"locale":"de-DE","permalink":"/de-DE/docs/references/paper"},{"locale":"fr-FR","permalink":"/fr-FR/docs/references/paper"},{"locale":"it-IT","permalink":"/it-IT/docs/references/paper"},{"locale":"tr-TR","permalink":"/tr-TR/docs/references/paper"},{"locale":"uk-UA","permalink":"/uk-UA/docs/references/paper"},{"locale":"ru-RU","permalink":"/ru-RU/docs/references/paper"},{"locale":"zh-CN","permalink":"/zh-CN/docs/references/paper"},{"locale":"ja-JP","permalink":"/ja-JP/docs/references/paper"},{"locale":"ko-KR","permalink":"/ko-KR/docs/references/paper"},{"locale":"hi-IN","permalink":"/hi-IN/docs/references/paper"},{"locale":"id-ID","permalink":"/id-ID/docs/references/paper"}]}'),a=o(4848),r=o(8453);let t={id:"paper",title:"Security-Driven Hardening: una convenzione per l'era dello sviluppo assistito dall'IA",sidebar_label:"Articolo sulla metodologia",description:"La metodologia Security-Driven Hardening (SDH): una convenzione blue team sensibile al contesto per verificare e mettere in sicurezza il software sviluppato con l'aiuto dell'IA o in vibe coding.",keywords:["Security-Driven Hardening","SDH","sicurezza difensiva","hardening","spec-driven development","articolo di Lagune"],source_hash:"030038fc3c922aec5f2f0a11d4dc5a15b92756c7dd17606378f27ad1c018c82b"},l="Security-Driven Hardening (SDH): una convenzione per l'era dello sviluppo assistito dall'IA",s=[{value:"Abstract",id:"abstract",level:2},{value:"I. Introduzione: la lacuna di sicurezza aperta dallo sviluppo assistito dall&#39;IA",id:"i-introduzione-la-lacuna-di-sicurezza-aperta-dallo-sviluppo-assistito-dallia",level:2},{value:"II. Contesto e lavori correlati",id:"ii-contesto-e-lavori-correlati",level:2},{value:"III. SDH: definizione e principi di progettazione",id:"iii-sdh-definizione-e-principi-di-progettazione",level:2},{value:"IV. Il flusso Blue Team in cinque fasi",id:"iv-il-flusso-blue-team-in-cinque-fasi",level:2},{value:"charter (policy)",id:"charter-policy",level:3},{value:"detect (detect)",id:"detect-detect",level:3},{value:"plan (triage)",id:"plan-triage",level:3},{value:"harden (remediate)",id:"harden-remediate",level:3},{value:"verify (verify)",id:"verify-verify",level:3},{value:"V. Chiudibilit\xe0: un rilievo ha uno stato finale",id:"v-chiudibilit\xe0-un-rilievo-ha-uno-stato-finale",level:2},{value:"VI. La dualit\xe0 dell&#39;estensore delle conoscenze dello sviluppatore",id:"vi-la-dualit\xe0-dellestensore-delle-conoscenze-dello-sviluppatore",level:2},{value:"VII. Specializzazioni non invocabili e prompt su richiesta",id:"vii-specializzazioni-non-invocabili-e-prompt-su-richiesta",level:2},{value:"VIII. Indipendenza dallo stato e adattivit\xe0 non autoritaria",id:"viii-indipendenza-dallo-stato-e-adattivit\xe0-non-autoritaria",level:2},{value:"Indipendenza dallo stato",id:"indipendenza-dallo-stato",level:3},{value:"Adattivit\xe0 non autoritaria",id:"adattivit\xe0-non-autoritaria",level:3},{value:"IX. La modalit\xe0 preventiva universale: la stessa difesa mentre si costruisce il lavoro",id:"ix-la-modalit\xe0-preventiva-universale-la-stessa-difesa-mentre-si-costruisce-il-lavoro",level:2},{value:"X. Security-Driven Hardening a confronto con lo Spec-Driven Development",id:"x-security-driven-hardening-a-confronto-con-lo-spec-driven-development",level:2},{value:"XI. Rigore ingegneristico: la disciplina del tracciamento",id:"xi-rigore-ingegneristico-la-disciplina-del-tracciamento",level:2},{value:"XII. Il veicolo: un&#39;architettura indipendente dall&#39;agente come prova di portabilit\xe0",id:"xii-il-veicolo-unarchitettura-indipendente-dallagente-come-prova-di-portabilit\xe0",level:2},{value:"XIII. Caso pratico: SDH dall&#39;inizio alla fine",id:"xiii-caso-pratico-sdh-dallinizio-alla-fine",level:2},{value:"XIV. Quando usare SDH, e i suoi limiti",id:"xiv-quando-usare-sdh-e-i-suoi-limiti",level:2},{value:"XV. Discussione: posizionamento, limiti e ci\xf2 che SDH non afferma",id:"xv-discussione-posizionamento-limiti-e-ci\xf2-che-sdh-non-afferma",level:2},{value:"Estende, non sostituisce",id:"estende-non-sostituisce",level:3},{value:"Solo difesa, per costruzione",id:"solo-difesa-per-costruzione",level:3},{value:"La verifica \xe8 sostanziale, non scenica",id:"la-verifica-\xe8-sostanziale-non-scenica",level:3},{value:"Il determinismo \xe8 circoscritto, e dichiarato",id:"il-determinismo-\xe8-circoscritto-e-dichiarato",level:3},{value:"Costi e scala",id:"costi-e-scala",level:3},{value:"L&#39;utente \xe8 l&#39;arbitro finale",id:"lutente-\xe8-larbitro-finale",level:3},{value:"Obiezioni e risposte",id:"obiezioni-e-risposte",level:3},{value:"XVI. Le insidie, e come SDH le evita per struttura",id:"xvi-le-insidie-e-come-sdh-le-evita-per-struttura",level:2},{value:"XVII. Sviluppi futuri",id:"xvii-sviluppi-futuri",level:2},{value:"XVIII. Conclusione",id:"xviii-conclusione",level:2},{value:"Riferimenti",id:"riferimenti",level:2},{value:"Appendice A: i principi, alla lettera",id:"appendice-a-i-principi-alla-lettera",level:2}];function c(e){let i={a:"a",blockquote:"blockquote",code:"code",em:"em",h2:"h2",h3:"h3",hr:"hr",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(i.ul,{children:["\n",(0,a.jsx)(i.li,{children:(0,a.jsx)(i.strong,{children:"Weslley Ara\xfajo"})}),"\n",(0,a.jsx)(i.li,{children:(0,a.jsx)(i.strong,{children:"Articolo sulla metodologia, 2026."})}),"\n"]}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"abstract",children:"Abstract"}),"\n",(0,a.jsx)(i.p,{children:"Security-Driven Hardening (SDH) \xe8 una metodologia di sicurezza strutturata, guidata dall'IA ed esclusivamente difensiva, pensata per un'epoca in cui il software viene scritto sempre pi\xf9 spesso da agenti IA e da persone che non sono specialisti di sicurezza. Invece di seguire una checklist generica, SDH rileva prima cosa fa davvero un sistema (login, caricamento di file, pagamenti, esposizione di dati e cos\xec via) e poi guida il lavoro di sicurezza specifico per quel contesto. \xc8 governata da principi sicuri per impostazione predefinita, \xe8 interamente orientata alla difesa ed \xe8 espressa in linguaggio semplice, cos\xec che qualsiasi utente possa agire di conseguenza."}),"\n",(0,a.jsxs)(i.p,{children:["Questo documento sostiene che SDH \xe8 una convenzione mancante, non un singolo strumento. Le conoscenze di sicurezza risiedono nella metodologia e nelle sue specializzazioni su richiesta, una base su cui ogni utente pu\xf2 costruire, e questo le permette di servire un principiante e un esperto attraverso lo stesso flusso. Due propriet\xe0 la distinguono dagli approcci spec-first precedenti ",(0,a.jsx)(i.code,{children:"[1]"}),". SDH \xe8 ",(0,a.jsx)(i.strong,{children:"indipendente dallo stato"}),": si adatta a una directory vuota, a un progetto in corso, a una singola pull request o a una grande codebase legacy, in qualsiasi stack. E SDH ",(0,a.jsx)(i.strong,{children:"si pu\xf2 chiudere"}),": un rischio verificato come chiuso viene archiviato e tolto dall'intero flusso, cos\xec quel rilievo raggiunge uno stato definitivo e viene riaperto solo quando il codice cambia. SDH non sostituisce i professionisti della sicurezza n\xe9 gli strumenti Blue Team specializzati. Estende le conoscenze dello sviluppatore stesso, e pi\xf9 uno sviluppatore capisce di sicurezza, pi\xf9 pu\xf2 guidarla."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Lagune"})," \xe8 l'implementazione di riferimento, e dimostra che la metodologia \xe8 realizzabile e portabile. SDH viene proposta come una convenzione che altri possono adottare."]}),"\n",(0,a.jsxs)(i.blockquote,{children:["\n",(0,a.jsx)(i.p,{children:(0,a.jsx)(i.strong,{children:"Parole chiave"})}),"\n",(0,a.jsx)(i.p,{children:"Sviluppo assistito dall'IA, sicurezza del software, sicurezza difensiva, spec-driven development, hardening di sicurezza, flussi di lavoro guidati da agenti, chiudibilit\xe0, sicurezza sensibile al contesto, conoscenza su richiesta, strumenti indipendenti dall'agente."}),"\n"]}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"i-introduzione-la-lacuna-di-sicurezza-aperta-dallo-sviluppo-assistito-dallia",children:"I. Introduzione: la lacuna di sicurezza aperta dallo sviluppo assistito dall'IA"}),"\n",(0,a.jsxs)(i.p,{children:["Il software viene rilasciato sempre pi\xf9 spesso da persone, e da agenti IA, che non sanno riconoscere in modo affidabile un pattern non sicuro: un segreto esposto, un controllo di autorizzazione mancante, una query vulnerabile all'injection. Non sono rischi esotici. Rientrano tra le classi di rischio che dominano gli incidenti reali, documentate da anni in riferimenti pubblici ",(0,a.jsx)(i.code,{children:"[6]"}),", ",(0,a.jsx)(i.code,{children:"[7]"}),", e studi recenti riportano che una quota significativa del codice generato dall'IA viene rilasciata proprio con difetti di questo tipo ",(0,a.jsx)(i.code,{children:"[8]"}),'. Gli assistenti di programmazione con IA hanno reso il problema acuto permettendo a chi non \xe8 sviluppatore di rilasciare software reale, ma la lacuna \xe8 pi\xf9 ampia di qualsiasi singolo pubblico. La maggior parte dei progetti non riceve mai un passaggio di sicurezza specifico per ci\xf2 che fa davvero. L\'ecosistema diventa pi\xf9 fragile a ogni decisione prematura del tipo "funziona, rilascialo".']}),"\n",(0,a.jsx)(i.p,{children:"I consigli di sicurezza generici non colmano questa lacuna. Una checklist statica non \xe8 specifica per ci\xf2 che fa un sistema, quindi sommerge un piccolo progetto di voci irrilevanti e manca comunque il rischio che conta per quel progetto. Il problema non \xe8 la scarsit\xe0 di conoscenze di sicurezza nel mondo. Il problema \xe8 abbinare la conoscenza giusta al sistema che l'utente ha davvero davanti, e farlo per qualcuno che potrebbe non sapere cosa chiedere."}),"\n",(0,a.jsxs)(i.p,{children:["SDH risponde con un'unica inversione: ",(0,a.jsx)(i.strong,{children:"le conoscenze di sicurezza risiedono nella specifica e nelle sue specializzazioni su richiesta, una base su cui ogni utente pu\xf2 costruire"}),". La metodologia rileva il contesto, classifica i rischi che quel contesto comporta e guida le correzioni, cos\xec uno sviluppatore e chi non lo \xe8 vengono serviti attraverso lo stesso flusso. I rilievi e le raccomandazioni restano in linguaggio semplice, quindi sono utilizzabili qualunque sia la preparazione tecnica di chi legge. L'esperto non ne \xe8 limitato, ma potenziato, una dualit\xe0 che sviluppiamo in ",(0,a.jsx)(i.code,{children:"\xa7VI"}),"."]}),"\n",(0,a.jsxs)(i.blockquote,{children:["\n",(0,a.jsx)(i.p,{children:(0,a.jsx)(i.strong,{children:"Concetto chiave"})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"L'inversione centrale:"})," le conoscenze di sicurezza risiedono nella specifica e nelle sue specializzazioni su richiesta, una base su cui ogni utente pu\xf2 costruire. La metodologia scopre cosa fa il sistema, vi abbina il lavoro di sicurezza ed estende ci\xf2 che l'utente gi\xe0 sa."]}),"\n"]}),"\n",(0,a.jsx)(i.p,{children:'Prendi uno sviluppatore che dice a un assistente IA: "la mia app permette agli utenti di caricare una foto del profilo". Senza un passaggio di sicurezza, l\'assistente produce codice funzionante che si fida in silenzio di tutto ci\xf2 che invia il client: il tipo di file dichiarato, il nome del file, la dimensione. Il caricamento va in produzione, e un file camuffato da immagine pu\xf2 contenere codice, un nome costruito ad arte pu\xf2 uscire dal percorso di archiviazione, un file troppo grande pu\xf2 esaurire le risorse del server. Niente di tutto questo si vede in una demo, quindi va in produzione.'}),"\n",(0,a.jsx)(i.p,{children:"Lo stesso codice, passato attraverso SDH, si comporta in modo diverso. SDH rileva che il sistema accetta file dall'esterno (detect), lo traduce nei rischi che un caricamento comporta (triage), propone di controllare il tipo reale e la dimensione del file, di rinominarlo al salvataggio e di conservarlo dove il codice non pu\xf2 essere eseguito (remediate), poi legge il risultato e conferma che ogni controllo regga davvero (verify). Lo sviluppatore non ha mai dovuto conoscere l'espressione \"unrestricted file upload\". Gliel'ha fornita la metodologia."}),"\n",(0,a.jsx)(i.p,{children:"Questo documento offre i seguenti contributi:"}),"\n",(0,a.jsxs)(i.ul,{children:["\n",(0,a.jsxs)(i.li,{children:["Una definizione precisa di SDH come metodologia, indipendente da qualsiasi implementazione, con i suoi principi di progettazione (",(0,a.jsx)(i.code,{children:"\xa7III"}),")."]}),"\n",(0,a.jsxs)(i.li,{children:["Un ciclo di vita difensivo in cinque fasi in cui la separazione dei compiti \xe8 essa stessa il contributo: il rilevamento non inventa mai, la pianificazione non legge mai il codice, una sola fase modifica il codice e la verifica non ammorbidisce mai il proprio giudizio (",(0,a.jsx)(i.code,{children:"\xa7IV"}),")."]}),"\n",(0,a.jsxs)(i.li,{children:["La ",(0,a.jsx)(i.strong,{children:"chiudibilit\xe0"})," come presa di posizione metodologica: un singolo rilievo ha uno stato finale, non un ciclo infinito (",(0,a.jsx)(i.code,{children:"\xa7V"}),")."]}),"\n",(0,a.jsxs)(i.li,{children:["La dualit\xe0 dell'",(0,a.jsx)(i.strong,{children:"estensore delle conoscenze dello sviluppatore"}),": un unico flusso che protegge il principiante e potenzia l'esperto (",(0,a.jsx)(i.code,{children:"\xa7VI"}),")."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"Specializzazioni non invocabili e prompt su richiesta"}),": conoscenze di sicurezza mirate che l'agente carica quando il contesto del progetto lo richiede, mai per impostazione predefinita (",(0,a.jsx)(i.code,{children:"\xa7VII"}),")."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"Indipendenza dallo stato"})," e ",(0,a.jsx)(i.strong,{children:"adattivit\xe0 non autoritaria"}),": SDH si adatta a qualsiasi stato di sviluppo e allo scenario, invece di imporre un ambito fisso (",(0,a.jsx)(i.code,{children:"\xa7VIII"}),")."]}),"\n",(0,a.jsxs)(i.li,{children:["Una ",(0,a.jsx)(i.strong,{children:"modalit\xe0 preventiva"}),": la stessa difesa eseguita mentre si costruisce il lavoro ordinario, cos\xec il codice nasce sicuro per impostazione predefinita e le fasi hanno meno da correggere (",(0,a.jsx)(i.code,{children:"\xa7IX"}),")."]}),"\n",(0,a.jsxs)(i.li,{children:["Un confronto dedicato con lo Spec-Driven Development, la tradizione da cui SDH \xe8 nata e da cui poi si \xe8 distaccata (",(0,a.jsx)(i.code,{children:"\xa7X"}),")."]}),"\n",(0,a.jsxs)(i.li,{children:["Le discipline di ingegneria che permettono alla metodologia di sopravvivere ai refactoring e di restare indipendente da qualsiasi agente: il tracciamento dell'identit\xe0 per nome (",(0,a.jsx)(i.code,{children:"\xa7XI"}),") e un veicolo indipendente dall'agente (",(0,a.jsx)(i.code,{children:"\xa7XII"}),")."]}),"\n"]}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"ii-contesto-e-lavori-correlati",children:"II. Contesto e lavori correlati"}),"\n",(0,a.jsxs)(i.p,{children:["SDH si basa su lavori precedenti. Eredita una struttura collaudata dallo sviluppo spec-first guidato da agenti ",(0,a.jsx)(i.code,{children:"[1]"}),", ",(0,a.jsx)(i.code,{children:"[2]"}),", ",(0,a.jsx)(i.code,{children:"[3]"}),": template, comandi slash consumati da un agente, un documento di governo e un agente che esegue le fasi. Reimplementa quella struttura con uno scopo difensivo. La discendenza \xe8 voluta, e uno dei principi di lavoro di SDH la nomina esplicitamente: costruire il flusso di lavoro a partire da una struttura collaudata, poi inquadrarlo per la sicurezza."]}),"\n",(0,a.jsx)(i.p,{children:"SDH non \xe8 una checklist statica di raccomandazioni generiche. Una checklist sa moltissimo della sicurezza in generale e nulla del progetto che ha davanti. SDH ribalta questa enfasi. Dedica il suo primo sforzo al rilevamento, a scoprire cosa fa il sistema, e solo dopo attinge alla conoscenza che il rilevamento rende pertinente."}),"\n",(0,a.jsxs)(i.p,{children:["SDH non sostituisce nemmeno le persone che si occupano di sicurezza o gli strumenti Blue Team specializzati. \xc8 un estensore delle conoscenze dello sviluppatore (",(0,a.jsx)(i.code,{children:"\xa7VI"}),"). Un team con una funzione di sicurezza dedicata dovrebbe mantenerla. SDH d\xe0 a quel team un veicolo strutturato, e a un team che non ne ha una d\xe0 una base difendibile."]}),"\n",(0,a.jsxs)(i.p,{children:["SDH si affianca anche agli scanner di sicurezza deterministici (analisi statica, linter) ",(0,a.jsx)(i.code,{children:"[4]"}),", ",(0,a.jsx)(i.code,{children:"[5]"}),". Quegli strumenti sono preziosi proprio perch\xe9 sono deterministici e ripetibili. SDH si basa soprattutto sul ragionamento dell'agente, e scambia il determinismo rigoroso con la sensibilit\xe0 al contesto. La metodologia non finge il contrario. Dove il determinismo conta, incorpora un motore deterministico all'interno del ragionamento (",(0,a.jsx)(i.code,{children:"\xa7VII"}),"): l'agente decide se vale la pena controllare un input, e un programma deterministico decide se quell'input \xe8 pericoloso."]}),"\n",(0,a.jsxs)(i.p,{children:["Il precedente pi\xf9 diretto \xe8 lo Spec-Driven Development (SDD), la famiglia di metodologie spec-first che porta avanti uno sviluppo a partire da una specifica eseguibile. Trattiamo l'SDD come una classe. La sua formulazione pi\xf9 chiara come metodologia per professionisti \xe8 il report di Piskala ",(0,a.jsx)(i.code,{children:"[1]"}),", e il suo toolkit guidato da agenti pi\xf9 visibile \xe8 Spec Kit di GitHub ",(0,a.jsx)(i.code,{children:"[2]"}),", con OpenSpec ",(0,a.jsx)(i.code,{children:"[3]"})," come secondo strumento della stessa famiglia. Questi sono i riferimenti canonici per il confronto in ",(0,a.jsx)(i.code,{children:"\xa7X"}),"."]}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"iii-sdh-definizione-e-principi-di-progettazione",children:"III. SDH: definizione e principi di progettazione"}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Security-Driven Hardening"})," \xe8 una metodologia di sicurezza strutturata e guidata dall'IA che rende una codebase pi\xf9 sicura portando avanti il lavoro a partire da una specifica eseguita dall'agente, invece che da correzioni improvvisate. Il nome si ispira ai ",(0,a.jsx)(i.strong,{children:"Blue Team"}),", i difensori nel campo della sicurezza. SDH riguarda la difesa, l'hardening e la verifica, mai l'attacco."]}),"\n",(0,a.jsxs)(i.blockquote,{children:["\n",(0,a.jsx)(i.p,{children:(0,a.jsx)(i.strong,{children:"Definizione"})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Security-Driven Hardening (SDH):"})," una metodologia di sicurezza strutturata, guidata dall'IA ed esclusivamente difensiva che rileva prima cosa fa davvero un sistema, poi guida il lavoro di sicurezza specifico per quel contesto, governata da principi sicuri per impostazione predefinita ed espressa in linguaggio semplice."]}),"\n"]}),"\n",(0,a.jsx)(i.p,{children:"SDH \xe8 definita da un insieme di principi vincolanti. Ognuno \xe8 una regola, e ognuno offre all'utente una garanzia specifica."}),"\n",(0,a.jsxs)(i.table,{children:[(0,a.jsx)(i.thead,{children:(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.th,{children:"Principio"}),(0,a.jsx)(i.th,{children:"La regola"}),(0,a.jsx)(i.th,{children:"Cosa garantisce all'utente"})]})}),(0,a.jsxs)(i.tbody,{children:[(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Sicuro per impostazione predefinita, in linguaggio semplice, per tutti allo stesso modo"}),(0,a.jsx)(i.td,{children:"Ogni impostazione predefinita, messaggio e correzione \xe8 sicuro fin da subito e comprensibile a chiunque legga, sviluppatore o no. Nessuna categoria di utenti \xe8 privilegiata."}),(0,a.jsx)(i.td,{children:"Un principiante riceve una base sicura senza chiederla, e legge il risultato con parole sue."})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Sensibile al contesto pi\xf9 che generico"}),(0,a.jsx)(i.td,{children:"Ogni fase parte dal contesto rilevato in detect e agisce su ci\xf2 che il sistema fa davvero."}),(0,a.jsx)(i.td,{children:"Le raccomandazioni si adattano al progetto, non a una checklist. Le conoscenze di sicurezza risiedono nella specifica e nelle sue specializzazioni su richiesta, ed estendono ci\xf2 che l'utente porta con s\xe9."})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Flessibile pi\xf9 che rigido"}),(0,a.jsx)(i.td,{children:"Principi, requisiti e raccomandazioni sono punti di partenza. L'utente pu\xf2 riformulare, eliminare, aggiungere o restringere qualsiasi cosa."}),(0,a.jsx)(i.td,{children:"La metodologia si piega al progetto e all'utente, e mai pi\xf9 rigidamente di quanto l'utente voglia. La flessibilit\xe0 non indebolisce mai la base sicura per impostazione predefinita."})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Riconciliare, mai solo aggiungere"}),(0,a.jsx)(i.td,{children:"Gli artefatti sono documenti vivi, non log. Ogni esecuzione ricontrolla ogni voce: mantiene ci\xf2 che regge, riscrive ci\xf2 che \xe8 cambiato, rimuove ci\xf2 che non vale pi\xf9."}),(0,a.jsx)(i.td,{children:"Il registro riflette sempre il presente, quindi non degenera mai in un arretrato superato."})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Solo difesa"}),(0,a.jsx)(i.td,{children:"SDH verifica, mette in sicurezza e controlla. Non produce mai strumenti offensivi, exploit per uso malevolo o tecniche di elusione del rilevamento per nuocere."}),(0,a.jsx)(i.td,{children:"La metodologia non pu\xf2 essere trasformata in un'arma. I contenuti a doppio uso compaiono solo in un contesto chiaramente difensivo."})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Spec-first, guidato da agenti, orientato alla sicurezza"}),(0,a.jsx)(i.td,{children:"Il flusso di lavoro \xe8 costruito a partire da template, comandi, un charter di governo e un agente che esegue le fasi."}),(0,a.jsx)(i.td,{children:"Una struttura di sviluppo collaudata, riadattata perch\xe9 sia l'agente a svolgere il lavoro di sicurezza sostanziale."})]})]})]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Tabella 1."})," I principi di progettazione di SDH e la garanzia che ognuno offre all'utente."]}),"\n",(0,a.jsxs)(i.p,{children:["Questi principi non sono ornamentali. Sono i vincoli che ogni fase descritta qui sotto deve rispettare, e la discussione in ",(0,a.jsx)(i.code,{children:"\xa7XV"})," vi ritorna per segnare i limiti della metodologia."]}),"\n",(0,a.jsx)(i.p,{children:"Il resto del documento sviluppa nove pilastri con un nome. Sono le parti che chi legge dovrebbe riuscire a tenere a mente, e quelle che un altro team dovrebbe reimplementare per poter dire di fare SDH."}),"\n",(0,a.jsxs)(i.table,{children:[(0,a.jsx)(i.thead,{children:(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.th,{children:"Pilastro"}),(0,a.jsx)(i.th,{children:"Cosa offre"}),(0,a.jsx)(i.th,{children:"Sezione"})]})}),(0,a.jsxs)(i.tbody,{children:[(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"L'inversione sensibile al contesto"}),(0,a.jsx)(i.td,{children:"Le conoscenze di sicurezza risiedono nella specifica e nelle sue specializzazioni su richiesta, cos\xec un principiante e un esperto condividono un unico flusso."}),(0,a.jsxs)(i.td,{children:[(0,a.jsx)(i.code,{children:"\xa7I"}),", ",(0,a.jsx)(i.code,{children:"\xa7VI"})]})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Il ciclo di vita difensivo in cinque fasi"}),(0,a.jsx)(i.td,{children:"Separazione dei compiti: policy, detect, triage, remediate, verify, ognuna con un solo compito."}),(0,a.jsx)(i.td,{children:(0,a.jsx)(i.code,{children:"\xa7IV"})})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"La chiudibilit\xe0"}),(0,a.jsx)(i.td,{children:"Un rilievo ha uno stato finale, non un ciclo infinito. Il lavoro chiuso viene archiviato."}),(0,a.jsx)(i.td,{children:(0,a.jsx)(i.code,{children:"\xa7V"})})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"La dualit\xe0 dell'estensore delle conoscenze dello sviluppatore"}),(0,a.jsx)(i.td,{children:"Un unico flusso che protegge il principiante e potenzia l'esperto, senza mai sostituire nessuno dei due."}),(0,a.jsx)(i.td,{children:(0,a.jsx)(i.code,{children:"\xa7VI"})})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Prompt su richiesta, conoscenza non invocabile"}),(0,a.jsx)(i.td,{children:"La conoscenza di sicurezza pertinente viene caricata per ci\xf2 che \xe8 il progetto, mai per impostazione predefinita."}),(0,a.jsx)(i.td,{children:(0,a.jsx)(i.code,{children:"\xa7VII"})})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Indipendenza dallo stato e adattivit\xe0 non autoritaria"}),(0,a.jsx)(i.td,{children:"Si adatta a qualsiasi stato di sviluppo in qualsiasi stack, e allo scenario invece di imporre un ambito."}),(0,a.jsx)(i.td,{children:(0,a.jsx)(i.code,{children:"\xa7VIII"})})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"La modalit\xe0 preventiva"}),(0,a.jsx)(i.td,{children:"La stessa difesa agisce mentre si costruisce il nuovo lavoro, cos\xec il codice nasce sicuro per impostazione predefinita."}),(0,a.jsx)(i.td,{children:(0,a.jsx)(i.code,{children:"\xa7IX"})})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Il tracciamento dell'identit\xe0 per nome"}),(0,a.jsx)(i.td,{children:"Un rilievo resta un unico elemento attraverso le fasi, e una rinomina rompe il collegamento in un solo punto."}),(0,a.jsx)(i.td,{children:(0,a.jsx)(i.code,{children:"\xa7XI"})})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Il veicolo indipendente dall'agente"}),(0,a.jsx)(i.td,{children:"Il valore di sicurezza viene scritto una sola volta e non dipende da alcun agente o stack."}),(0,a.jsx)(i.td,{children:(0,a.jsx)(i.code,{children:"\xa7XII"})})]})]})]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Tabella 2."})," I nove pilastri di SDH e dove viene sviluppato ciascuno."]}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"iv-il-flusso-blue-team-in-cinque-fasi",children:"IV. Il flusso Blue Team in cinque fasi"}),"\n",(0,a.jsx)(i.p,{children:"SDH struttura il lavoro come un ciclo di vita difensivo in cinque fasi (Figura 1). Ogni fase \xe8 orientata alla difesa, ognuna si basa sulla precedente, e le fasi seguono la reale attivit\xe0 di un Blue Team: stabilire una policy, rilevare, classificare, porre rimedio, verificare."}),"\n",(0,a.jsx)(i.pre,{children:(0,a.jsx)(i.code,{className:"language-mermaid",children:'flowchart TB\n    charter["1 \xb7 charter (policy)<br/>legge: il progetto, e la descrizione dell\'utente se fornita<br/>scrive: il charter<br/>i principi indicano il rischio che prevengono, in linguaggio semplice"]\n    detect["2 \xb7 detect (detect)<br/>legge: il codice dell\'utente<br/>scrive: la mappa di detect<br/>rilevare, non inventare: registrare solo ci\xf2 che il codice sostiene"]\n    plan["3 \xb7 plan (triage)<br/>legge: la mappa di detect, mai il codice<br/>scrive: il piano di difesa<br/>ogni correzione punta a qualcosa che detect ha davvero mappato"]\n    harden["4 \xb7 harden (remediate)<br/>legge: il piano di difesa, e il codice che tocca<br/>scrive: il codice, e il registro di hardening<br/>l\'unica fase che modifica il codice, una correzione alla volta, la modifica minima che regge"]\n    verify["5 \xb7 verify (verify)<br/>legge: il codice, e il registro di hardening<br/>scrive: ogni verdetto aperto sul registro di hardening<br/>il confronto tra codice e registro, statico, mai ammorbidito"]\n    charter --\x3e detect --\x3e plan --\x3e harden --\x3e verify\n    verify -.->|"bocciata: lavoro riaperto per harden,<br/>riapplicato in base al motivo registrato"| harden\n    verify -.->|"chiusura: archivia ci\xf2 che ha dimostrato chiuso<br/>in tutta la catena,<br/>una riga nello storico"| detect\n'})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Figura 1."})," Il flusso in cinque fasi: cosa legge ogni fase, cosa scrive e la sua invariante portante. Verify guida entrambi i ritorni: un controllo bocciato riapre harden, e un rilievo dimostrato chiuso viene archiviato in tutta la catena, con una riga nello storico."]}),"\n",(0,a.jsx)(i.p,{children:"La separazione dei compiti \xe8 il contributo. Dato che ogni fase ha un solo compito, una modalit\xe0 di guasto resta confinata in un punto, e chi legge pu\xf2 fidarsi di ci\xf2 che ogni artefatto dichiara."}),"\n",(0,a.jsxs)(i.blockquote,{children:["\n",(0,a.jsx)(i.p,{children:(0,a.jsx)(i.strong,{children:"Concetto chiave"})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Applicata non significa verificata:"}),' harden registra che una correzione \xe8 stata applicata. Verify la verifica confrontando il codice con quel registro, e il verdetto non viene mai ammorbidito per farlo coincidere con il registro. Un controllo pu\xf2 essere presente nel codice e lasciare comunque raggiungibile il rischio, e allora il verdetto onesto \xe8 "Risk not closed".']}),"\n"]}),"\n",(0,a.jsx)(i.h3,{id:"charter-policy",children:"charter (policy)"}),"\n",(0,a.jsxs)(i.p,{children:["Il charter stabilisce i principi di sicurezza del progetto, le regole che ogni fase successiva deve rispettare. \xc8 il livello di governo, una sorta di controllo in fase di compilazione della postura di sicurezza del progetto. Ogni principio ha un nome chiaro, una regola non negoziabile che si pu\xf2 verificare sul codice e una riga ",(0,a.jsx)(i.code,{children:"Why:"})," che indica il rischio che previene, non solo la correzione. Il charter legge sempre il progetto stesso (i suoi manifest, la sua struttura e le sue dipendenze), e la descrizione dell'utente, quando c'\xe8, \xe8 una direzione che la lettura poi allarga oltre ci\xf2 che l'utente ha nominato. Senza descrizione, il progetto \xe8 l'unica fonte. Le due si sommano invece di competere, e il charter registra la policy a cui il progetto dovrebbe attenersi, non lo stato del suo codice. Chi non \xe8 sviluppatore dovrebbe poterlo leggere e capire sia la regola sia il rischio."]}),"\n",(0,a.jsx)(i.h3,{id:"detect-detect",children:"detect (detect)"}),"\n",(0,a.jsxs)(i.p,{children:["Detect legge il codice e mappa ci\xf2 che il sistema fa davvero e che ha un peso per la sicurezza. L'istruzione guida \xe8 \"rilevare, non inventare\": registrare solo ci\xf2 che il codice sostiene, con le evidenze di cui hanno bisogno le fasi successive. Detect \xe8 neutrale. Non costringe i suoi rilievi ad adattarsi al charter, perch\xe9 confrontare i rischi con le regole del charter \xe8 compito della fase plan. Ogni rilievo ha tre parti: cos'\xe8 (descrizione in linguaggio semplice), perch\xe9 conta (il rischio, non solo il fatto) e l'evidenza (la funzione o la route in cui si trova). L'evidenza non contiene alcun percorso di file. Il percorso si trova solo nella mappa di tracciamento (",(0,a.jsx)(i.code,{children:"\xa7XI"}),"), cos\xec la prosa non contiene mai un percorso che possa diventare obsoleto."]}),"\n",(0,a.jsx)(i.h3,{id:"plan-triage",children:"plan (triage)"}),"\n",(0,a.jsx)(i.p,{children:"Plan trasforma ogni rilievo in una correzione, indicata con la sua classe di rischio (citando i riferimenti consolidati, CWE e OWASP, dove la sostengono) e legata al principio del charter che la correzione rispetta. La priorit\xe0 (Critical, High, Medium, Low) non \xe8 una scelta libera: plan valuta ogni rilievo con il metodo Base ed Environmental di CVSS v4.0, quindi la fascia \xe8 il punteggio espresso a parole, giustificato da una riga in linguaggio semplice su esposizione e posta in gioco, e due esecuzioni producono lo stesso ordine. Il vettore \xe8 l'ancora precisa per un esperto, la fascia e la sua giustificazione la stessa valutazione che chiunque pu\xf2 seguire. Plan lavora solo a partire dalla mappa di detect e non legge mai il codice. \xc8 un vincolo voluto, non un limite: obbliga ogni correzione a puntare a qualcosa che detect ha davvero rilevato. Se un ambito non \xe8 mai stato mappato, plan si ferma e rimanda l'utente a detect invece di tirare a indovinare."}),"\n",(0,a.jsx)(i.h3,{id:"harden-remediate",children:"harden (remediate)"}),"\n",(0,a.jsx)(i.p,{children:"Harden \xe8 l'unica fase che modifica il codice, quindi procede con cautela. Se una modifica richieda l'approvazione dell'utente dipende dall'agente e dalla modalit\xe0 di permessi in cui viene eseguito, quindi harden non aggiunge alcun passaggio di conferma proprio. Applica una correzione alla volta, prima le dipendenze, poi la priorit\xe0 pi\xf9 alta, cos\xec ogni modifica resta piccola, revisionabile e facile da annullare. Non indebolisce mai un controllo esistente per far quadrare una nuova correzione, e non viola mai un principio del charter. Se una correzione entrasse in conflitto con un principio, harden si ferma e fa emergere il conflitto invece di applicarla. Ogni blocco viene registrato come Applied, Partial o Blocked. \"Applicata non significa ancora verificata\", ed \xe8 la questione di cui si occupa la fase successiva."}),"\n",(0,a.jsx)(i.h3,{id:"verify-verify",children:"verify (verify)"}),"\n",(0,a.jsx)(i.p,{children:"Verify verifica ogni controllo applicato leggendo il codice e confrontandolo con ci\xf2 che harden ha registrato. La verifica \xe8 proprio quel confronto, codice contro registro, ed \xe8 statica: conferma che un controllo \xe8 presente e corretto nel codice, non che il controllo regga sotto attacco su un sistema in esecuzione. Quel controllo a runtime, del tipo che esegue attacchi reali o simulati contro il sistema in produzione, \xe8 fuori ambito per scelta progettuale. Verify restituisce uno di tre verdetti: Risk closed, Risk not closed o Cannot tell from the code. Non produce alcun artefatto proprio: harden e verify condividono il registro di hardening, harden possiede ci\xf2 che \xe8 stato fatto e verify il verdetto e il suo motivo, e nessuno dei due scrive mai nei campi dell'altro. Un controllo bocciato \xe8 lavoro riaperto per harden, la cui esecuzione successiva considera il verdetto prevalente sulla propria lettura del codice e riapplica la correzione sulla lacuna esatta indicata dal motivo. Verify si fida del codice pi\xf9 che del registro, perch\xe9 un registro pu\xf2 dichiarare pi\xf9 di quanto il codice offra. \xc8 in sola lettura sul codice dell'utente, e non ammorbidisce mai un verdetto per farlo coincidere con il registro. Un controllo pu\xf2 essere presente e lasciare comunque il rischio raggiungibile per un'altra via, e in quel caso il verdetto onesto \xe8 \"Risk not closed\". Se, durante la lettura, verify nota un problema di sicurezza che la mappa di detect non ha mai coperto, non inventa un verdetto, perch\xe9 rilevare \xe8 compito di detect: fa emergere il problema e rimanda l'utente a detect, cos\xec il rilievo entra attraverso lo stesso flusso invece di aggirarlo."}),"\n",(0,a.jsxs)(i.blockquote,{children:["\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Filo conduttore: il caricamento di file."})," Un singolo rilievo mostra la spina dorsale dall'inizio alla fine."]}),"\n",(0,a.jsxs)(i.ul,{children:["\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"detect"})," lo trova: il sistema accetta file dagli utenti, e l'handler del caricamento si fida del tipo MIME inviato dal client senza controllare il tipo reale del file. ",(0,a.jsx)(i.em,{children:"Perch\xe9 conta:"})," un file camuffato da immagine pu\xf2 nascondere codice malevolo."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"plan"})," decide la correzione, priorit\xe0 ",(0,a.jsx)(i.strong,{children:"Critical"}),', nel rispetto del principio "Ogni input \xe8 non attendibile finch\xe9 non viene validato": controllare il tipo reale e la dimensione del file, rinominarlo al salvataggio e conservare i caricamenti dove non possono essere eseguiti come codice.']}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"harden"})," la applica, stato ",(0,a.jsx)(i.strong,{children:"Applied"}),": ora l'handler rileva il tipo reale dal contenuto, impone un limite di dimensione, rifiuta tutto ci\xf2 che \xe8 inatteso, rinomina al salvataggio e conserva dove il codice non pu\xf2 essere eseguito."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"verify"})," legge l'handler, lo confronta con il registro e restituisce ",(0,a.jsx)(i.strong,{children:"Risk closed"}),": il codice fa esattamente ci\xf2 che dichiara il registro."]}),"\n"]}),"\n",(0,a.jsxs)(i.p,{children:["Lo stesso nome del rilievo attraversa la mappa di detect, il piano e il registro di hardening, e verify agisce su quel registro con lo stesso nome: un verdetto aperto viene scritto nel blocco del rilievo, e un rilievo dimostrato chiuso viene archiviato (",(0,a.jsx)(i.code,{children:"\xa7V"}),"). Quel nome condiviso \xe8 la sua identit\xe0 (",(0,a.jsx)(i.code,{children:"\xa7XI"}),")."]}),"\n"]}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"v-chiudibilit\xe0-un-rilievo-ha-uno-stato-finale",children:"V. Chiudibilit\xe0: un rilievo ha uno stato finale"}),"\n",(0,a.jsxs)(i.p,{children:["La maggior parte degli strumenti di sicurezza lascia all'utente un arretrato che non fa che crescere. SDH adotta una posizione diversa: ",(0,a.jsx)(i.strong,{children:"un rilievo si pu\xf2 chiudere, quindi ha uno stato finale invece di vivere in un arretrato infinito"})," (Figura 2). Questo deriva direttamente dal principio di riconciliazione."]}),"\n",(0,a.jsxs)(i.blockquote,{children:["\n",(0,a.jsx)(i.p,{children:(0,a.jsx)(i.strong,{children:"Definizione"})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Chiudibilit\xe0:"})," un rischio verificato come chiuso viene archiviato e tolto dall'intero flusso, cos\xec quel rilievo raggiunge uno stato definitivo e viene riaperto solo quando il codice cambia. Un rilievo ha uno stato finale, anche se il programma di sicurezza in s\xe9 resta continuo."]}),"\n"]}),"\n",(0,a.jsx)(i.p,{children:"Gli artefatti di SDH sono documenti vivi, non log. Ogni volta che una fase viene rieseguita, ricontrolla ogni voce esistente rispetto alla verit\xe0 attuale e fa una di tre cose: mantiene ci\xf2 che \xe8 ancora valido, riscrive ci\xf2 che \xe8 cambiato o rimuove ci\xf2 che non vale pi\xf9. Un rilievo che il codice mostra ormai risolto viene semplicemente rimosso. Il registro di lavoro riflette il presente, non il passato."}),"\n",(0,a.jsx)(i.p,{children:"La chiusura \xe8 quella stessa riconciliazione che arriva alla sua conclusione. Quando verify verifica che un rischio \xe8 chiuso, archivia il rilievo in tutto il flusso: la mappa di detect, il piano, il registro di hardening e la mappa di tracciamento. Per questo verify \xe8 l'unica fase che scrive negli artefatti delle altre fasi: \xe8 la fase che chiude il cerchio. Mentre il rilievo lascia la catena, l'archiviazione lo distilla in una breve voce di un registro storico che vive fuori dalla catena di lavoro e non viene mai rielaborato. \xc8 questo il confine tra sparire e chiudersi: un rilievo che la riconciliazione ha rimosso perch\xe9 ha smesso di essere vero non lascia nulla dietro di s\xe9, mentre un rilievo dimostrato chiuso si guadagna la sua riga nello storico. Un rilievo archiviato \xe8 poi assente da ogni artefatto di lavoro, e questa assenza \xe8 attesa, non una catena rotta."}),"\n",(0,a.jsx)(i.pre,{children:(0,a.jsx)(i.code,{className:"language-mermaid",children:"stateDiagram-v2\n    direction TB\n    [*] --\x3e OPEN: detect rileva\n    OPEN --\x3e Plan: plan\n    Plan --\x3e Harden: harden\n    Harden --\x3e Verify: verify\n    Verify --\x3e StoodDown: Risk closed\n    StoodDown --\x3e SETTLED\n    SETTLED --\x3e OPEN: modifiche al codice riaprono un rilievo\n    Plan: plan\n    Harden: harden\n    Verify: verify\n    StoodDown: ARCHIVIATO \xb7 una riga nello storico\n"})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Figura 2."})," La macchina a stati della chiudibilit\xe0. Un rilievo passa da OPEN ad ARCHIVIATO a SETTLED, e si riapre solo quando il codice cambia."]}),"\n",(0,a.jsx)(i.p,{children:"Quando tutto ci\xf2 che rientra nell'ambito \xe8 archiviato, il ciclo \xe8 a riposo, e lo stato di riposo ha una forma concreta: un artefatto il cui ultimo rilievo \xe8 stato chiuso viene rimosso per intero, quindi una catena completamente chiusa lascia solo il charter e lo storico, la policy e la prova. Il ciclo si riapre solo quando il codice cambia. La metodologia d\xe0 a ogni rilievo una fine definita, ed \xe8 esattamente ci\xf2 che un arretrato infinito non pu\xf2 fare."}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"vi-la-dualit\xe0-dellestensore-delle-conoscenze-dello-sviluppatore",children:"VI. La dualit\xe0 dell'estensore delle conoscenze dello sviluppatore"}),"\n",(0,a.jsxs)(i.p,{children:["SDH non sostituisce le persone, e non sostituisce gli strumenti Blue Team specializzati. ",(0,a.jsx)(i.strong,{children:"Estende le conoscenze dello sviluppatore stesso"}),". Pi\xf9 uno sviluppatore capisce di sicurezza, pi\xf9 precisamente pu\xf2 guidare il flusso, e pi\xf9 autonomia ha. Uno sviluppatore che ne capisce poco riceve comunque un risultato sicuro, perch\xe9 la modalit\xe0 automatica lo tutela."]}),"\n",(0,a.jsxs)(i.p,{children:["L'inversione di ",(0,a.jsx)(i.code,{children:"\xa7I"}),", le conoscenze di sicurezza che risiedono nella specifica, vale in entrambe le direzioni. Per il principiante \xe8 protezione: non ha bisogno di sapere cosa chiedere, perch\xe9 la specifica propone. Per l'esperto \xe8 potenziamento: la stessa specifica gli permette di indirizzare il flusso con precisione invece di lavorare contro una checklist fissa."]}),"\n",(0,a.jsx)(i.p,{children:"Ogni fase porta questa dualit\xe0 nel proprio funzionamento (Figura 3). Eseguita senza input, agisce sull'intero ambito per conto dell'utente. Con un'indicazione, la stessa fase si restringe esattamente a ci\xf2 su cui l'utente l'ha puntata."}),"\n",(0,a.jsx)(i.pre,{children:(0,a.jsx)(i.code,{className:"language-mermaid",children:'flowchart TB\n    inversion["un\'inversione, due direzioni:<br/>le conoscenze di sicurezza risiedono nella specifica"]\n    inversion --\x3e auto["modalit\xe0 automatica (nessun input)<br/>la fase propone e agisce<br/>sull\'intero ambito"]\n    inversion --\x3e directed["modalit\xe0 guidata (con input)<br/>la fase si restringe esattamente<br/>a ci\xf2 su cui l\'utente l\'ha puntata"]\n    auto --\x3e novice["il principiante, protetto:<br/>un risultato sicuro senza<br/>sapere cosa chiedere"]\n    directed --\x3e expert["l\'esperto, potenziato:<br/>il flusso indirizzato con precisione,<br/>non una checklist fissa"]\n    novice -.-> phases["le stesse cinque fasi servono entrambi:<br/>charter \xb7 detect \xb7 plan \xb7 harden \xb7 verify"]\n    expert -.-> phases\n'})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Figura 3."})," La dualit\xe0 dell'estensore delle conoscenze dello sviluppatore. Un'unica inversione serve due pubblici: la modalit\xe0 automatica protegge il principiante e la modalit\xe0 guidata potenzia l'esperto, attraverso le stesse cinque fasi."]}),"\n",(0,a.jsxs)(i.p,{children:["Le specializzazioni su richiesta (",(0,a.jsx)(i.code,{children:"\xa7VII"}),") rendono esplicita la dualit\xe0 nel loro stesso testo. Ognuna dice all'agente che la sua conoscenza \"estende il tuo giudizio\" e di continuare a ragionare oltre ci\xf2 che la specializzazione fornisce. La conoscenza \xe8 un pavimento, non un soffitto. \xc8 questo che serve entrambi i pubblici nell'equilibrio voluto dal documento: la comunit\xe0 degli sviluppatori ottiene uno strumento sostanziale, e il professionista Blue Team ottiene un veicolo strutturato che non finge di fare il suo lavoro al posto suo."]}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"vii-specializzazioni-non-invocabili-e-prompt-su-richiesta",children:"VII. Specializzazioni non invocabili e prompt su richiesta"}),"\n",(0,a.jsxs)(i.p,{children:["\xc8 lo schema pi\xf9 innovativo della metodologia. SDH porta conoscenze di sicurezza mirate sotto forma di specializzazioni che si caricano ",(0,a.jsx)(i.strong,{children:"solo su richiesta"}),", ed \xe8 l'agente stesso a decidere quali caricare, abbinandole al contesto del progetto. Lo chiamiamo ",(0,a.jsx)(i.strong,{children:"prompt su richiesta"}),": un modo per l'agente di scegliere quale conoscenza attivare in base all'ambito del progetto in cui si trova, invece di eseguire ogni controllo per impostazione predefinita. Le specializzazioni sono evolutive, e ognuna pu\xf2 cambiare o essere sostituita in qualsiasi momento. Il contributo \xe8 lo schema, non le specializzazioni in s\xe9."]}),"\n",(0,a.jsxs)(i.blockquote,{children:["\n",(0,a.jsx)(i.p,{children:(0,a.jsx)(i.strong,{children:"Definizione"})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Prompt su richiesta:"})," l'agente seleziona quale conoscenza di sicurezza attivare confrontandola con l'ambito del progetto che ha davanti, cos\xec la conoscenza pertinente viene richiamata per ci\xf2 che il progetto \xe8 davvero, invece di eseguire ogni controllo per impostazione predefinita."]}),"\n"]}),"\n",(0,a.jsxs)(i.blockquote,{children:["\n",(0,a.jsx)(i.p,{children:(0,a.jsx)(i.strong,{children:"Definizione"})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Specializzazione non invocabile:"})," un'unit\xe0 di conoscenza di sicurezza mirata e indipendente dal linguaggio per un singolo contesto, come il caricamento di file o il codice che gira nel browser. Verifica e spiega, non riscrive mai il codice e non produce mai un input di attacco. Non \xe8 un comando: si carica quando il contesto che copre rientra nell'ambito, o quando un prompt la richiede per nome."]}),"\n"]}),"\n",(0,a.jsx)(i.p,{children:"Ogni specializzazione indica le forme pi\xf9 sicure per i rischi che copre e dice all'agente come agire su un rilievo in ogni fase che la utilizza: come giudicarlo nel rilevamento, come applicarne la correzione in sicurezza nel rimedio e come dimostrarla nella verifica."}),"\n",(0,a.jsxs)(i.p,{children:["Il tratto distintivo \xe8 che una specializzazione \xe8 ",(0,a.jsx)(i.strong,{children:"non invocabile da sola"}),": non \xe8 un comando, e all'interno del flusso \xe8 una corrispondenza a caricarla. La fase di rilevamento elenca il catalogo una volta, confronta il contesto del progetto con ci\xf2 che copre ogni voce e carica solo le specializzazioni il cui contesto \xe8 presente nell'ambito. Le fasi successive riutilizzano quell'elenco invece di rielencare, cos\xec un'unica corrispondenza serve l'intera catena, e la modalit\xe0 preventiva (",(0,a.jsx)(i.code,{children:"\xa7IX"}),") esegue la stessa corrispondenza sul lavoro che sta per essere costruito. Una specializzazione il cui contesto \xe8 assente viene saltata, e il salto deve essere giustificato quanto il caricamento: ogni voce del catalogo riceve un verdetto esplicito, applicata o saltata con il motivo ricavato dal codice, cos\xec una vaga impressione di irrilevanza non prende mai il posto dell'assenza. Non trovarne nessuna applicabile \xe8 un esito valido."]}),"\n",(0,a.jsxs)(i.p,{children:["Il catalogo \xe8 fatto di dati, e la crescita \xe8 un file di conoscenza pi\xf9 una riga di catalogo, mai un nuovo comando. Le specializzazioni integrate sono raggruppate in categorie, come OWASP, un linguaggio o le integrazioni di IA, e il catalogo usato da un progetto contiene le specializzazioni integrate delle categorie scelte pi\xf9 le sue specializzazioni. Il progetto registra quella scelta insieme al resto del suo stato, cos\xec tutto il team lavora sullo stesso catalogo. \xc8 lo stesso principio di sensibilit\xe0 al contesto delle fasi, applicato alla conoscenza: la conoscenza pertinente viene richiamata per ci\xf2 che il progetto \xe8 davvero, invece di eseguire ogni controllo per impostazione predefinita. La stessa propriet\xe0 permette all'utente, non solo al maintainer, di far crescere il catalogo: una fonte o un tema di sicurezza fornito dall'utente viene distillato in una nuova specializzazione che appartiene al progetto, entra nel suo catalogo qualunque siano le categorie e si carica esattamente come una integrata, sostituendo quella integrata con lo stesso nome. Anche scrivere una specializzazione \xe8 un'attivit\xe0 esclusivamente difensiva e rispetta lo stesso confine che le specializzazioni fanno valere: la descrizione di un attacco pu\xf2 essere la fonte, ma la specializzazione che ne deriva verifica e spiega, e non emette mai un exploit funzionante. Cos\xec l'inversione di ",(0,a.jsx)(i.code,{children:"\xa7I"}),", l'intelligenza che risiede nella specifica, si estende al catalogo stesso, che l'utente pu\xf2 approfondire per il proprio contesto senza scrivere codice."]}),"\n",(0,a.jsx)(i.p,{children:"Un breve esempio illustra il prompt su richiesta. Detect legge una cartella di codice che gira nel browser. Abbina quel contesto nel catalogo, carica la specializzazione che lo copre e fa emergere un rilievo lato client attraverso i normali passi di detect. Le specializzazioni il cui contesto \xe8 assente da questo ambito non corrispondono, quindi non si caricano mai, e ognuna viene registrata come saltata. \xc8 stato il progetto a decidere quale conoscenza fosse pertinente, non una configurazione fissa."}),"\n",(0,a.jsxs)(i.p,{children:["Il determinismo compare proprio dove conta. Una specializzazione pu\xf2 portare con s\xe9 un controllo deterministico, non solo prosa: dove una classe di rischio ha una procedura di decisione netta, un piccolo programma restituisce un verdetto fisso per un dato input, per esempio un breve insieme di parole come ",(0,a.jsx)(i.code,{children:"safe"}),", ",(0,a.jsx)(i.code,{children:"unsafe"})," o ",(0,a.jsx)(i.code,{children:"invalid input"}),". Alcune classi di rischio si possono decidere in modo deterministico esattamente cos\xec, con un corpus di lavori precedenti alla base della procedura di decisione ",(0,a.jsx)(i.code,{children:"[9]"}),", ",(0,a.jsx)(i.code,{children:"[10]"}),", ",(0,a.jsx)(i.code,{children:"[11]"}),". Il controllo valuta i candidati forniti dall'agente oppure analizza l'ambito per trovarli da solo, e in entrambi i casi \xe8 il controllo, non l'agente, a restituire il verdetto. Una specializzazione abbastanza universale pu\xf2 essere contrassegnata come obbligatoria nel catalogo e viene allora sempre applicata, con il suo controllo eseguito sull'intero ambito. \xc8 l'unico caso in cui la conoscenza si carica senza una corrispondenza di contesto, ed \xe8 dichiarato nei dati del catalogo, mai deciso dall'agente sul momento. \xc8 qui che SDH ancora il ragionamento dell'agente a qualcosa di ripetibile, senza fingere che l'intero flusso sia deterministico."]}),"\n",(0,a.jsxs)(i.p,{children:["Infine, le specializzazioni sono ",(0,a.jsx)(i.strong,{children:"separabili"}),". Dato che la conoscenza sta in piedi da sola, un utente pu\xf2 eseguirne una direttamente in un prompt che non ha nulla a che fare con il flusso SDH completo, tenendo la sicurezza accanto allo sviluppo ordinario. Una specializzazione con un controllo deterministico pu\xf2, per esempio, vagliare ogni candidato prodotto durante la normale scrittura del codice e tenere solo quelli sicuri. Questa separabilit\xe0 \xe8 uno dei motivi per cui SDH si adatta a cos\xec tante situazioni, che sono l'oggetto di ",(0,a.jsx)(i.code,{children:"\xa7VIII"}),", e la sua espressione completa \xe8 la modalit\xe0 preventiva (",(0,a.jsx)(i.code,{children:"\xa7IX"}),"), in cui la stessa conoscenza protegge lo sviluppo ordinario dall'inizio alla fine."]}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"viii-indipendenza-dallo-stato-e-adattivit\xe0-non-autoritaria",children:"VIII. Indipendenza dallo stato e adattivit\xe0 non autoritaria"}),"\n",(0,a.jsx)(i.p,{children:"Due propriet\xe0 separano SDH dalle metodologie di specifica rigide."}),"\n",(0,a.jsx)(i.h3,{id:"indipendenza-dallo-stato",children:"Indipendenza dallo stato"}),"\n",(0,a.jsxs)(i.blockquote,{children:["\n",(0,a.jsx)(i.p,{children:(0,a.jsx)(i.strong,{children:"Definizione"})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Indipendenza dallo stato:"})," la metodologia non dipende dallo stato di sviluppo. Si adatta a una directory vuota, a un progetto in corso, a una singola pull request o a una grande codebase legacy, in qualsiasi stack, perch\xe9 scopre il punto di partenza leggendolo."]}),"\n"]}),"\n",(0,a.jsx)(i.p,{children:"Ogni fase funziona allo stesso modo, che il progetto sia nuovo di zecca o esista gi\xe0. Il charter deduce i principi da qualunque codice sia presente. Detect mappa qualunque codice ci sia, anche se \xe8 pochissimo. Non c'\xe8 alcun punto di partenza presupposto."}),"\n",(0,a.jsx)(i.h3,{id:"adattivit\xe0-non-autoritaria",children:"Adattivit\xe0 non autoritaria"}),"\n",(0,a.jsxs)(i.blockquote,{children:["\n",(0,a.jsx)(i.p,{children:(0,a.jsx)(i.strong,{children:"Definizione"})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Adattivit\xe0 non autoritaria:"})," la metodologia si adatta allo scenario invece di imporre un ambito fisso che l'utente deve seguire. Quando l'utente non sa cosa dire, legge l'ambiente in cui \xe8 stata invocata, genera contesto e pone le domande che orientano ci\xf2 che far\xe0 dopo."]}),"\n"]}),"\n",(0,a.jsx)(i.p,{children:"La modalit\xe0 di proposta del charter \xe8 il caso pi\xf9 chiaro: SDH ricava un charter sicuro per impostazione predefinita analizzando il progetto, chiedendo all'utente solo quando una lacuna cambia davvero il risultato, poi lo scrive e presenta ogni principio in linguaggio semplice con il rischio che previene. Il charter \xe8 un documento vivo che l'utente rielabora rieseguendolo, non un contratto subordinato a una richiesta di approvazione, quindi non richiede mai all'utente di sapere cosa chiedere."}),"\n",(0,a.jsx)(i.p,{children:"Questa adattivit\xe0 si manifesta come sensibilit\xe0 alla forma dell'input: la stessa fase legge ci\xf2 che ha ricevuto e sceglie una modalit\xe0 (Figura 4). Un file nel prompt, un rilievo dall'elenco, un timore, una missione mirata contro un punto debole noto o la richiesta di un'analisi completa a tappeto: ognuno risponde al bisogno dell'utente, perch\xe9 il flusso \xe8 non autoritario per scelta progettuale. Niente di tutto questo indebolisce la base sicura per impostazione predefinita. La flessibilit\xe0 plasma il modo in cui la base viene applicata, non la abbassa mai."}),"\n",(0,a.jsx)(i.pre,{children:(0,a.jsx)(i.code,{className:"language-mermaid",children:'flowchart TB\n    shape["la fase legge la forma<br/>di ci\xf2 che ha ricevuto"]\n    shape --\x3e none["nessun input"]\n    shape --\x3e paths["uno o pi\xf9 percorsi"]\n    shape --\x3e concern["una preoccupazione descritta"]\n    shape --\x3e finding["un rilievo con nome"]\n    shape --\x3e band["una fascia di priorit\xe0"]\n    none --\x3e auto["la modalit\xe0 automatica:<br/>proporre, o analizzare<br/>l\'intero ambito"]\n    paths --\x3e focus["concentrarsi solo su quei<br/>file o directory"]\n    concern --\x3e scoped["limitarsi a quella<br/>sola preoccupazione"]\n    finding --\x3e item["agire su quel singolo<br/>elemento tracciato"]\n    band --\x3e priority["agire solo su Critical,<br/>High, Medium o Low"]\n'})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Figura 4."})," Adattivit\xe0 non autoritaria. La stessa fase legge la forma del suo input e sceglie una modalit\xe0, cos\xec l'ambito \xe8 sempre dell'utente, mai imposto."]}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"ix-la-modalit\xe0-preventiva-universale-la-stessa-difesa-mentre-si-costruisce-il-lavoro",children:"IX. La modalit\xe0 preventiva universale: la stessa difesa mentre si costruisce il lavoro"}),"\n",(0,a.jsx)(i.p,{children:"SDH porta con s\xe9 una modalit\xe0 complementare: lo sviluppo ordinario svolto con la stessa difesa attiva mentre il codice viene scritto. L'utente chiede il lavoro in s\xe9, una pagina di login, un caricamento, un endpoint, e la metodologia protegge lo sviluppo mentre avviene, cos\xec il risultato \xe8 sicuro per impostazione predefinita nel momento in cui arriva, invece che dopo un successivo passaggio di hardening."}),"\n",(0,a.jsxs)(i.blockquote,{children:["\n",(0,a.jsx)(i.p,{children:(0,a.jsx)(i.strong,{children:"Definizione"})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"La modalit\xe0 preventiva:"})," lo sviluppo ordinario eseguito sotto il livello di governo e la conoscenza di SDH. Il charter vincola lo sviluppo, le specializzazioni pertinenti a ci\xf2 che sta per essere creato si caricano su richiesta, e il risultato viene confrontato esattamente con la difesa usata prima che il lavoro sia considerato concluso."]}),"\n"]}),"\n",(0,a.jsxs)(i.p,{children:["La modalit\xe0 riutilizza ogni elemento che le fasi gi\xe0 portano con s\xe9, puntato su codice che non esiste ancora. Il rilevamento del contesto passa dal codice all'intento: l'agente ragiona su ci\xf2 che sta per costruire e sui confini che quel lavoro attraversa (un login implica credenziali, una sessione e input dall'esterno), ed \xe8 con quel ragionamento che viene confrontato il catalogo delle conoscenze. Il prompt su richiesta (",(0,a.jsx)(i.code,{children:"\xa7VII"}),") si generalizza qui: il contesto si pu\xf2 rilevare nel piano per il codice, non solo nel codice che esiste. Il charter governa come sempre, e una richiesta che violerebbe un principio viene fatta emergere come conflitto, mai costruita. La difesa viene applicata in linea, nel momento in cui ogni parte viene scritta, validando al confine e scegliendo il costrutto sicuro fin dalla prima volta, cos\xec una versione funzionante ma non sicura non esiste mai e non c'\xe8 nulla da correggere."]}),"\n",(0,a.jsx)(i.p,{children:"La modalit\xe0 finisce dove inizia verify. Prima che il lavoro sia considerato concluso, chi lo costruisce confronta il proprio risultato con la difesa che ha usato: il controllo deve trovarsi sul percorso del rischio, non accanto, deve essere completo e, dove una specializzazione porta con s\xe9 un controllo deterministico, il verdetto del controllo prevale sulla lettura dell'agente stesso. Una lacuna trovata qui viene chiusa come parte dello stesso lavoro, perch\xe9 finire il lavoro significa finirlo in sicurezza."}),"\n",(0,a.jsxs)(i.p,{children:["Ci\xf2 che la modalit\xe0 rifiuta \xe8 voluto quanto ci\xf2 che fa. Costruisce solo ci\xf2 che \xe8 stato chiesto e non verifica nulla di ci\xf2 che sta intorno: verificare ci\xf2 che esiste spetta alle fasi. Non scrive alcun artefatto e non traccia alcun rilievo, perch\xe9 un rilievo \xe8 un rischio individuato in ci\xf2 che esiste, e lo scopo di questa modalit\xe0 \xe8 che la versione non sicura non arrivi mai. Le due direzioni si completano a vicenda: le fasi chiudono ci\xf2 che c'\xe8 gi\xe0 (",(0,a.jsx)(i.code,{children:"\xa7V"}),"), e la modalit\xe0 preventiva impedisce al nuovo lavoro di riaprirlo. Una catena a riposo resta a riposo non perch\xe9 lo sviluppo si sia fermato, ma perch\xe9 ci\xf2 che si costruisce mentre riposa viene costruito gi\xe0 difeso."]}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"x-security-driven-hardening-a-confronto-con-lo-spec-driven-development",children:"X. Security-Driven Hardening a confronto con lo Spec-Driven Development"}),"\n",(0,a.jsxs)(i.p,{children:["Security-Driven Hardening (SDH) \xe8 nata dalla base dello Spec-Driven Development (SDD) e poi se n'\xe8 distaccata nettamente. L'eredit\xe0 strutturale \xe8 reale e riconosciuta: spec-first, guidato da agenti, un documento di governo e una serie di comandi a fasi che l'agente esegue. SDH riutilizza quella struttura deliberatamente. Ci\xf2 che cambia \xe8 lo scopo, il modello di autorit\xe0, lo stato presupposto e la condizione finale. Trattiamo l'SDD come una classe, usando il report di Piskala ",(0,a.jsx)(i.code,{children:"[1]"})," come formulazione canonica della metodologia, Spec Kit di GitHub ",(0,a.jsx)(i.code,{children:"[2]"})," come toolkit canonico per agenti e OpenSpec ",(0,a.jsx)(i.code,{children:"[3]"})," come secondo strumento della stessa famiglia."]}),"\n",(0,a.jsxs)(i.p,{children:["L'SDD capovolge lo sviluppo tradizionale rendendo eseguibili le specifiche: la specifica genera direttamente un'implementazione funzionante invece di limitarsi a guidarla ",(0,a.jsx)(i.code,{children:"[1]"}),". Il suo insieme di fasi porta avanti uno sviluppo ",(0,a.jsx)(i.code,{children:"[2]"})," (stabilire i principi di governo, specificare cosa costruire, pianificare lo stack tecnologico, suddividere il piano in task, poi implementare). Il suo documento di governo, una costituzione di principi, \xe8 l'elemento fondante a cui l'agente deve attenersi in ogni momento. \xc8 questo il cuore della differenza. Nell'SDD l'autorit\xe0 scorre dalla specifica verso lo sviluppo, e ci si aspetta che l'implementazione la segua."]}),"\n",(0,a.jsx)(i.p,{children:"SDH ribalta quasi ogni asse di quel contratto (Tabella 3)."}),"\n",(0,a.jsxs)(i.blockquote,{children:["\n",(0,a.jsx)(i.p,{children:(0,a.jsx)(i.strong,{children:"Concetto chiave"})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"La differenza centrale:"})," nell'SDD l'autorit\xe0 scorre dalla specifica verso lo sviluppo, e ci si aspetta che l'implementazione la segua. SDH \xe8 non autoritaria e scorre nella direzione opposta, verso l'interno a partire dal contesto rilevato del sistema, mettendo in sicurezza ci\xf2 che c'\xe8 gi\xe0."]}),"\n"]}),"\n",(0,a.jsxs)(i.table,{children:[(0,a.jsx)(i.thead,{children:(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.th,{children:"Asse"}),(0,a.jsx)(i.th,{children:"SDD"}),(0,a.jsx)(i.th,{children:"SDH"})]})}),(0,a.jsxs)(i.tbody,{children:[(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Obiettivo"}),(0,a.jsx)(i.td,{children:"Consegnare funzionalit\xe0. La specifica diventa un'implementazione funzionante."}),(0,a.jsx)(i.td,{children:"Mettere in sicurezza ci\xf2 che esiste o che si sta costruendo. Ogni fase \xe8 orientata alla difesa."})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Modello di autorit\xe0"}),(0,a.jsx)(i.td,{children:"Autoritario. La specifica e la costituzione confinano lo sviluppo in un ambito da seguire."}),(0,a.jsx)(i.td,{children:"Non autoritario. SDH si adatta allo scenario, e l'utente pu\xf2 riformulare, eliminare o restringere."})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Stato presupposto"}),(0,a.jsx)(i.td,{children:"Uno sviluppo in avanti a partire da una specifica."}),(0,a.jsx)(i.td,{children:"Indipendente dallo stato: directory vuota, progetto in corso, una singola PR o codice legacy."})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Condizione finale"}),(0,a.jsx)(i.td,{children:"Finisce quando la funzionalit\xe0 \xe8 costruita."}),(0,a.jsx)(i.td,{children:"Si pu\xf2 chiudere. Un rilievo raggiunge uno stato definitivo e si riapre solo quando il codice cambia."})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Documento di governo"}),(0,a.jsx)(i.td,{children:"Una costituzione di principi a cui l'agente deve attenersi."}),(0,a.jsxs)(i.td,{children:["Un charter di principi formulati in termini di rischio (ognuno con una riga ",(0,a.jsx)(i.code,{children:"Why:"}),"), esplicitamente non un contratto fisso."]})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Come cresce la conoscenza"}),(0,a.jsx)(i.td,{children:"Si aggiunge un comando (o si estende l'insieme di fasi)."}),(0,a.jsx)(i.td,{children:"Si aggiunge una specializzazione non invocabile che l'agente carica su richiesta: un file pi\xf9 una riga di catalogo, nessun nuovo comando."})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Chi serve"}),(0,a.jsx)(i.td,{children:"Chi costruisce e porta avanti una funzionalit\xe0."}),(0,a.jsx)(i.td,{children:"Qualsiasi utente, sviluppatore o no, servito attraverso lo stesso flusso."})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Cosa modifica il codice"}),(0,a.jsx)(i.td,{children:"La fase di implementazione genera lo sviluppo."}),(0,a.jsx)(i.td,{children:"Solo la fase harden modifica il codice, una correzione alla volta."})]})]})]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Tabella 3."})," SDD e SDH a confronto su otto assi. Struttura presa in prestito, contratto ribaltato."]}),"\n",(0,a.jsxs)(i.p,{children:["Per correttezza nei confronti della tradizione: l'SDD \xe8 un precedente collaudato, e SDH gli deve la struttura su cui gira. Il distacco non \xe8 una critica all'SDD, che risolve bene un problema diverso (costruire in avanti). SDH prende lo stesso meccanismo collaudato e lo punta verso la difesa, l'adattivit\xe0 e la chiusura. OpenSpec ",(0,a.jsx)(i.code,{children:"[3]"}),", organizzato intorno a proposte di modifica, elenchi di task e specifiche per ogni modifica, conferma lo schema: la famiglia porta avanti uno sviluppo a partire da una specifica, mentre SDH mette in sicurezza un sistema verso l'interno a partire dal suo contesto rilevato. Anche la modalit\xe0 preventiva di SDH (",(0,a.jsx)(i.code,{children:"\xa7IX"}),"), l'unico punto in cui accompagna uno sviluppo in avanti, mantiene il contratto ribaltato: governa il modo in cui il lavoro viene costruito e non decide mai cosa costruire."]}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"xi-rigore-ingegneristico-la-disciplina-del-tracciamento",children:"XI. Rigore ingegneristico: la disciplina del tracciamento"}),"\n",(0,a.jsxs)(i.p,{children:["La disciplina del riconciliare senza mai solo aggiungere (",(0,a.jsx)(i.code,{children:"\xa7V"}),") ha bisogno di un substrato che sopravviva ai refactoring. Un rilievo deve restare un unico elemento in ogni fase che lo tocca, e un file rinominato o spostato non deve rompere la catena. SDH risolve il problema con l'",(0,a.jsx)(i.strong,{children:"identit\xe0 per nome"})," e con ",(0,a.jsx)(i.strong,{children:"i percorsi conservati solo nel tracciamento"}),"."]}),"\n",(0,a.jsxs)(i.blockquote,{children:["\n",(0,a.jsx)(i.p,{children:(0,a.jsx)(i.strong,{children:"Definizione"})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Identit\xe0 per nome:"})," l'identit\xe0 di un rilievo \xe8 il suo nome, scritto in modo identico in ogni artefatto. La prosa contiene il nome, mai un percorso. I percorsi dei file si trovano solo nella mappa di tracciamento, cos\xec un file rinominato o spostato rompe il collegamento esattamente in un punto."]}),"\n"]}),"\n",(0,a.jsxs)(i.p,{children:["Ogni rilievo di detect \xe8 un elemento tracciato. La sua identit\xe0 \xe8 il suo ",(0,a.jsx)(i.strong,{children:"nome"}),", il titolo della sezione, scritto in modo identico nella mappa di detect, nel piano e nel registro di hardening. Le fasi successive riutilizzano quel nome alla lettera mentre agiscono sullo stesso elemento, e verify scrive il suo verdetto nel registro di hardening con quello stesso nome. La mappa di tracciamento contiene il tracciamento e nient'altro, una voce per elemento:"]}),"\n",(0,a.jsx)(i.pre,{children:(0,a.jsx)(i.code,{className:"language-json",children:'{ "name": "File uploads", "paths": ["src/routes/upload.ts"] }\n'})}),"\n",(0,a.jsx)(i.p,{children:"La mappa non registra prosa, annotazioni, identificatori separati n\xe9 fasi. Gli artefatti in prosa contengono la formulazione, e la mappa contiene solo identit\xe0 e percorsi. I percorsi dei file sono l'unico elemento volatile, e si trovano solo qui. Un file rinominato o spostato pu\xf2 rompere il collegamento esattamente in un punto, mai in due copie divergenti."}),"\n",(0,a.jsx)(i.pre,{children:(0,a.jsx)(i.code,{className:"language-mermaid",children:'flowchart TB\n    detect["la mappa di detect"] --\x3e name\n    plan["il piano di difesa"] --\x3e name\n    harden["il registro di hardening<br/>verify vi scrive il suo verdetto"] --\x3e name\n    name["name = &quot;File uploads&quot;<br/>la prosa contiene il nome, mai un percorso"]\n    name -.-> tracking\n    tracking["la mappa di tracciamento<br/>{ name: &quot;File uploads&quot;,<br/>paths: [&quot;src/routes/upload.ts&quot;] }<br/>il percorso si trova solo qui, quindi una rinomina corregge solo questa voce"]\n'})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Figura 5."})," Il trasportatore dell'identit\xe0. Il nome di un rilievo attraversa ogni artefatto, mentre il suo percorso si trova solo nella mappa di tracciamento, cos\xec una rinomina viene corretta in un solo punto."]}),"\n",(0,a.jsxs)(i.p,{children:["Due atti mantengono la mappa nel flusso normale, e un terzo si distingue come manutenzione. ",(0,a.jsx)(i.strong,{children:"Track"})," \xe8 una registrazione additiva: una fase riporta i rilievi che ha scritto, e il motore registra quelli nuovi e segue un percorso rinominato per gli altri, classificandoli come nuovi, spostati o invariati. Non rimuove mai nulla che la fase non abbia riportato. ",(0,a.jsx)(i.strong,{children:"Untrack"})," archivia i rilievi che verify ha chiuso: in un unico passaggio deterministico distilla ognuno nella sua voce di storico, rimuove la sua intera sezione dagli artefatti, elimina un artefatto il cui ultimo rilievo non c'\xe8 pi\xf9 ed elimina la sua voce di tracciamento, cos\xec l'agente non fa nulla di tutto ci\xf2 a mano. Dove il passaggio deterministico non pu\xf2 procedere in sicurezza, un nome archiviato ancora citato nella prosa di un altro rilievo, segnala il punto all'agente invece di tirare a indovinare una modifica. Questi due sono gli atti che le fasi richiamano durante l'esecuzione. ",(0,a.jsx)(i.strong,{children:"Repair"})," \xe8 l'atto di manutenzione: una fase lo delega automaticamente quando la propria riconciliazione trova il tracciamento incoerente (un percorso registrato che non esiste pi\xf9), e altrimenti viene eseguito su richiesta. Riallinea l'intera mappa in una volta sola, leggendo ogni artefatto e il codice attuale, correggendo i percorsi di ogni elemento e facendo emergere ci\xf2 che non pu\xf2 decidere da solo, un orfano (un elemento tracciato che nessun artefatto nomina pi\xf9) o un candidato alla rinomina (un elemento i cui percorsi corrispondono a un nome riportato diverso)."]}),"\n",(0,a.jsx)(i.p,{children:"Repair \xe8 manutenzione, non una sesta fase. Non tocca n\xe9 il codice dell'utente n\xe9 gli artefatti in prosa, solo il tracciamento. Legge il sorgente dell'utente per un unico motivo, scoprire il nuovo percorso di un file rinominato, e non scrive mai contenuti di sicurezza. La persona \xe8 l'arbitro finale sull'unica decisione che il motore si rifiuta di indovinare: se un elemento scomparso sia stato risolto o soltanto rinominato. Meglio chiedere che indovinare, perch\xe9 un elemento eliminato per errore rompe la catena."}),"\n",(0,a.jsx)(i.p,{children:"La metodologia applica a se stessa la propria disciplina difensiva. I motori deterministici vengono invocati come programmi da riga di comando, e ogni input viene passato come argomento di processo a s\xe9 stante, il che lo mantiene inerte, cos\xec un valore con virgolette o backtick non pu\xf2 mai iniettare nulla nel comando. Un controllo sconosciuto fallisce invece di rispondere, cos\xec un nome scritto male non risulta mai come un esito pulito. SDH non esenta la propria infrastruttura dal principio della sicurezza per impostazione predefinita."}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"xii-il-veicolo-unarchitettura-indipendente-dallagente-come-prova-di-portabilit\xe0",children:"XII. Il veicolo: un'architettura indipendente dall'agente come prova di portabilit\xe0"}),"\n",(0,a.jsx)(i.p,{children:"Perch\xe9 SDH sia una convenzione che altri adottano, non deve essere legata a un solo agente o a un solo stack, quindi il suo veicolo tiene separate tre responsabilit\xe0 (Figura 6). Lagune dimostra che \xe8 possibile."}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Il valore di sicurezza"})," viene scritto una sola volta e non sa nulla di quale agente lo esegua: le istruzioni delle fasi e i template che compilano, il catalogo delle conoscenze e i motori deterministici. ",(0,a.jsx)(i.strong,{children:"La distribuzione"})," \xe8 sottile: il suo unico compito \xe8 portare quel valore a un dato agente nella forma e nel posto che l'agente si aspetta, e non contiene alcuna logica di sicurezza propria. ",(0,a.jsx)(i.strong,{children:"Lo stato del progetto"})," appartiene al progetto: il charter, gli artefatti delle fasi, la mappa di tracciamento, le categorie scelte e le sue specializzazioni, versionati e revisionabili come qualsiasi altra parte del suo codice."]}),"\n",(0,a.jsx)(i.pre,{children:(0,a.jsx)(i.code,{className:"language-mermaid",children:'flowchart TB\n    value["il valore di sicurezza, scritto una sola volta<br/>istruzioni delle fasi \xb7 template \xb7 catalogo delle conoscenze \xb7 motori deterministici<br/>non sa nulla di quale agente lo esegua"]\n    delivery["la distribuzione<br/>porta quel valore a ogni agente nella forma che si aspetta<br/>non contiene logica di sicurezza"]\n    agent["l\'agente<br/>esegue le fasi"]\n    project["lo stato del progetto<br/>versionato con il suo codice<br/>charter \xb7 artefatti delle fasi \xb7 tracciamento \xb7 categorie \xb7 specializzazioni proprie"]\n    value --\x3e delivery --\x3e agent\n    agent --\x3e|"legge e scrive"| project\n'})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Figura 6."})," Il veicolo indipendente dall'agente. Il valore di sicurezza viene scritto una sola volta, una distribuzione sottile lo porta a ogni agente, e lo stato resta del progetto."]}),"\n",(0,a.jsx)(i.p,{children:"Dato che la distribuzione non contiene logica di sicurezza, il modo in cui viene costruita non cambia nulla in SDH. Un veicolo pu\xf2 costruire la distribuzione da s\xe9 o affidarla a un ecosistema che gi\xe0 distribuisce skill per agenti, come fa l'implementazione di riferimento, e le fasi, i loro artefatti e le loro garanzie restano gli stessi. Niente di tutto questo \xe8 specifico di un linguaggio o di un runtime. L'implementazione di riferimento \xe8 scritta in un certo stack, ma la metodologia \xe8 il confine tra queste responsabilit\xe0, non la toolchain che le costruisce. Lo stesso progetto si potrebbe reimplementare in un linguaggio completamente diverso senza cambiare ci\xf2 che SDH \xe8."}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"xiii-caso-pratico-sdh-dallinizio-alla-fine",children:"XIII. Caso pratico: SDH dall'inizio alla fine"}),"\n",(0,a.jsxs)(i.blockquote,{children:["\n",(0,a.jsx)(i.p,{children:(0,a.jsx)(i.strong,{children:"Caso pratico"})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Hardening difensivo di una superficie di caricamento e di amministrazione."}),"\n",(0,a.jsx)(i.strong,{children:"Contesto:"})," una piccola app che accetta file caricati dagli utenti e li elenca in una pagina di amministrazione.\n",(0,a.jsx)(i.strong,{children:"Schema:"})," charter \u2192 detect (con conoscenza su richiesta attivata dal contesto) \u2192 plan \u2192 harden \u2192 verify, con una chiusura e un fallimento reale.\n",(0,a.jsx)(i.strong,{children:"Esito (capacit\xe0):"})," un rischio verificato come chiuso e archiviato in tutta la catena, e un controllo verificato come ",(0,a.jsx)(i.em,{children:"non"})," chiuso e rimandato a harden. Il verdetto riflette il codice, non il registro."]}),"\n"]}),"\n",(0,a.jsx)(i.p,{children:(0,a.jsx)(i.em,{children:"Questo \xe8 un esempio illustrativo dei meccanismi della metodologia, non uno studio misurato sul campo, e non riporta metriche di efficacia."})}),"\n",(0,a.jsxs)(i.p,{children:["Un'unica dimostrazione continua mostra la metodologia in azione, non solo le sue parti. Estendiamo il filo del caricamento di file di ",(0,a.jsx)(i.code,{children:"\xa7IV"})," con un'attivazione di conoscenza su richiesta e una chiusura, e includiamo un fallimento reale."]}),"\n",(0,a.jsxs)(i.ol,{children:["\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"charter"}),' propone il principio "Ogni input \xe8 non attendibile finch\xe9 non viene validato", con il suo rischio in linguaggio semplice: l\'input non controllato \xe8 il modo pi\xf9 comune in cui un sistema viene violato.']}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"detect"})," analizza la route del caricamento e la piccola pagina di amministrazione che elenca i file caricati. Rileva il rilievo sul caricamento (l'handler si fida del tipo MIME del client). La pagina di amministrazione gira nel browser, un contesto che il prompt su richiesta (",(0,a.jsx)(i.code,{children:"\xa7VII"}),") riconosce, quindi detect carica la specializzazione per quel contesto e fa emergere un secondo rilievo, un punto in cui il nome di un file viene scritto nella pagina come markup invece che come testo, cos\xec un nome costruito ad arte pu\xf2 essere eseguito come script nel browser del visitatore. Le specializzazioni il cui contesto \xe8 assente da questo ambito non si caricano mai, e ogni salto viene registrato con l'assenza ricavata dal codice."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"plan"})," assegna alla correzione del caricamento la priorit\xe0 Critical, legata al principio: controllare il tipo reale e la dimensione del file, rinominarlo al salvataggio, conservarlo dove il codice non pu\xf2 essere eseguito. Assegna alla seconda correzione la priorit\xe0 High: mostrare il nome del file come testo, non come markup."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"harden"})," applica prima la correzione del caricamento (priorit\xe0 pi\xf9 alta) e la registra come Applied, poi la seconda, anch'essa Applied."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"verify"})," legge ogni punto e confronta il codice con il registro. Il controllo sul caricamento regge: l'handler rileva il tipo reale dal contenuto, impone un limite di dimensione e rifiuta il resto. Verdetto: Risk closed. Verify archivia il rilievo sul caricamento in tutta la catena, e il suo riepilogo distillato finisce nello storico."]}),"\n"]}),"\n",(0,a.jsx)(i.p,{children:'Segue il fallimento reale. Supponiamo che la seconda correzione di harden abbia aggiunto un helper sicuro per mostrare il testo, ma abbia lasciato la vecchia chiamata che scrive markup ancora raggiungibile da un altro percorso del codice. Verify legge la pagina, vede l\'helper sicuro e vede anche che il percorso non sicuro \xe8 ancora attivo. Il controllo \xe8 presente, ma il rischio non \xe8 chiuso. Verify si rifiuta di ammorbidire il verdetto per farlo coincidere con il registro. Restituisce "Risk not closed", registra la lacuna e rimanda a harden. Un controllo che non affronta completamente il rischio non \xe8 un via libera.'}),"\n",(0,a.jsx)(i.p,{children:"Questo \xe8 il carattere della metodologia in un solo esempio: rilevamento sensibile al contesto, correzioni con priorit\xe0 legate ai principi, applicazione attenta e una verifica che riporta lo stato reale del codice, qualunque cosa dica il registro."}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"xiv-quando-usare-sdh-e-i-suoi-limiti",children:"XIV. Quando usare SDH, e i suoi limiti"}),"\n",(0,a.jsxs)(i.p,{children:["SDH \xe8 raramente sproporzionata come pu\xf2 esserlo un processo pesante, perch\xe9 \xe8 indipendente dallo stato e si pu\xf2 chiudere: si riduce fino a un singolo file e a una singola preoccupazione, e raggiunge uno stato definitivo invece di lasciare un peso permanente. Il suo confine non \xe8 la dimensione del progetto, \xe8 la ",(0,a.jsx)(i.strong,{children:"profondit\xe0 della garanzia"}),"."]}),"\n",(0,a.jsx)(i.pre,{children:(0,a.jsx)(i.code,{className:"language-mermaid",children:'flowchart TB\n    q1{"Il codice fa qualcosa di rilevante per la sicurezza?<br/>(input, autenticazione, dati, segreti, chiamate esterne)"}\n    q1 --\x3e|no| little["Qui SDH aggiunge poco."]\n    q1 --\x3e|s\xec| q2{"Esegui SDH. C\'\xe8 un requisito di conformit\xe0,<br/>o una funzione di sicurezza dedicata?"}\n    q2 --\x3e|no| baseline["SDH \xe8 una base difendibile."]\n    q2 --\x3e|s\xec| carrier["SDH \xe8 il veicolo strutturato:<br/>supporta la revisione e l\'audit degli esperti,<br/>non li sostituisce."]\n'})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Figura 7."})," Quando usare SDH. La diramazione riguarda prima la rilevanza per la sicurezza, poi la profondit\xe0 della garanzia, mai la dimensione del progetto."]}),"\n",(0,a.jsx)(i.p,{children:"Dove SDH raggiunge il suo confine: i comportamenti che emergono solo quando il sistema \xe8 in esecuzione (verify legge il codice, non esegue il sistema), i rischi che dipendono da una configurazione o da un ambiente che l'agente non pu\xf2 leggere, e i contesti ad alto rischio in cui la revisione di un esperto \xe8 comunque necessaria. In ognuno di questi casi SDH aggiunge comunque valore come primo passaggio strutturato, ma \xe8 un pavimento, non un soffitto."}),"\n",(0,a.jsxs)(i.blockquote,{children:["\n",(0,a.jsx)(i.p,{children:(0,a.jsx)(i.strong,{children:"Concetto chiave"})}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Il confine:"})," il limite di SDH \xe8 la profondit\xe0 della garanzia, non la dimensione del progetto. Pu\xf2 fare da base difendibile quasi ovunque e supporta la revisione degli esperti dove la posta in gioco lo richiede, ma non sostituisce i test sul sistema in esecuzione n\xe9 il giudizio di un professionista della sicurezza."]}),"\n"]}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"xv-discussione-posizionamento-limiti-e-ci\xf2-che-sdh-non-afferma",children:"XV. Discussione: posizionamento, limiti e ci\xf2 che SDH non afferma"}),"\n",(0,a.jsx)(i.p,{children:"SDH \xe8 precisa sui propri confini."}),"\n",(0,a.jsx)(i.h3,{id:"estende-non-sostituisce",children:"Estende, non sostituisce"}),"\n",(0,a.jsxs)(i.p,{children:["SDH non sostituisce i professionisti della sicurezza n\xe9 gli strumenti Blue Team specializzati. Estende le conoscenze dello sviluppatore (",(0,a.jsx)(i.code,{children:"\xa7VI"}),"). L'affermazione corretta \xe8 misurata: applicata bene, SDH ",(0,a.jsx)(i.strong,{children:"pu\xf2"})," chiudere rischi reali in modo efficace, soprattutto per i progetti che altrimenti non riceverebbero alcun passaggio di sicurezza. Non \xe8 una garanzia, e non sostituisce la revisione di un esperto dove la posta in gioco la richiede."]}),"\n",(0,a.jsx)(i.h3,{id:"solo-difesa-per-costruzione",children:"Solo difesa, per costruzione"}),"\n",(0,a.jsx)(i.p,{children:"SDH verifica, mette in sicurezza e controlla. Non produce mai strumenti offensivi, exploit o tecniche di elusione del rilevamento per nuocere. I contenuti di sicurezza a doppio uso sono accettabili solo in un contesto chiaramente difensivo e autorizzato. \xc8 un confine rigido, non una preferenza."}),"\n",(0,a.jsx)(i.h3,{id:"la-verifica-\xe8-sostanziale-non-scenica",children:"La verifica \xe8 sostanziale, non scenica"}),"\n",(0,a.jsx)(i.p,{children:"Verify verifica leggendo il codice e confrontandolo con il registro, non eseguendo il sistema. \xc8 una verifica statica: conferma che un controllo \xe8 presente e corretto nel codice, e non dimostra che il controllo regga sotto attacco a runtime. Per questo \"Cannot tell from the code\" \xe8 un verdetto legittimo, non un fallimento nascosto dietro un esito positivo. Quando l'evidenza non \xe8 nel codice (dipende dalla configurazione, o da un percorso che l'agente non pu\xf2 leggere), SDH lo dice invece di tirare a indovinare."}),"\n",(0,a.jsx)(i.h3,{id:"il-determinismo-\xe8-circoscritto-e-dichiarato",children:"Il determinismo \xe8 circoscritto, e dichiarato"}),"\n",(0,a.jsxs)(i.p,{children:["Gran parte di SDH si basa sul ragionamento dell'agente, ed \xe8 questo che ne permette la sensibilit\xe0 al contesto. Il determinismo \xe8 riservato ai motori deterministici: i controlli che una specializzazione pu\xf2 portare con s\xe9 (",(0,a.jsx)(i.code,{children:"\xa7VII"}),") e il motore di tracciamento (",(0,a.jsx)(i.code,{children:"\xa7XI"}),"). Il documento non sfuma questo confine. Dove un risultato \xe8 deterministico, \xe8 il risultato di un programma. Dove \xe8 ragionato, \xe8 la lettura del codice da parte dell'agente, con l'utente come arbitro finale."]}),"\n",(0,a.jsx)(i.h3,{id:"costi-e-scala",children:"Costi e scala"}),"\n",(0,a.jsxs)(i.p,{children:["Un'analisi completa consuma molti token. Le modalit\xe0 manuali (",(0,a.jsx)(i.code,{children:"\xa7VI"}),", ",(0,a.jsx)(i.code,{children:"\xa7VIII"}),") esistono in parte per mantenere il costo proporzionato alla preoccupazione."]}),"\n",(0,a.jsx)(i.h3,{id:"lutente-\xe8-larbitro-finale",children:"L'utente \xe8 l'arbitro finale"}),"\n",(0,a.jsx)(i.p,{children:"SDH chiede alla persona di decidere tra rinominato e risolto, e l'approvazione delle sue modifiche al codice resta dove l'utente gi\xe0 governa il proprio agente, nella modalit\xe0 di permessi in cui lo esegue. La metodologia propone e verifica. Non scavalca la persona."}),"\n",(0,a.jsx)(i.h3,{id:"obiezioni-e-risposte",children:"Obiezioni e risposte"}),"\n",(0,a.jsx)(i.p,{children:"Uno scettico onesto sollever\xe0 diverse obiezioni. Quelle sostanziali meritano di essere poste con parole loro."}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:'"Non \xe8 solo un analizzatore statico con un LLM attaccato sopra?"'})," No. Un analizzatore statico esegue per impostazione predefinita ogni regola che ha. SDH rileva prima che cos'\xe8 il sistema, poi attinge alla conoscenza pertinente (",(0,a.jsx)(i.code,{children:"\xa7II"}),", ",(0,a.jsx)(i.code,{children:"\xa7VII"}),"), e ",(0,a.jsx)(i.em,{children:"incorpora"})," un controllo deterministico solo dove una classe di rischio ha una procedura di decisione netta. Il ragionamento parte dal contesto, il determinismo \xe8 mirato."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:'"Non \xe8 solo una checklist di sicurezza?"'})," No. SDH ribalta la checklist: il rilevamento viene prima, e la conoscenza viene richiamata per ci\xf2 che il progetto fa davvero (",(0,a.jsx)(i.code,{children:"\xa7II"}),", ",(0,a.jsx)(i.code,{children:"\xa7VII"}),")."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:'"Non \xe8 solo l\'SDD rinominato per la sicurezza?"'})," No. SDH prende in prestito la struttura dell'SDD e ne ribalta il contratto: autorit\xe0, stato presupposto, condizione finale e destinatari sono tutti diversi (",(0,a.jsx)(i.code,{children:"\xa7X"}),"). Stesso meccanismo, direzione opposta."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:'"Un metodo basato sul ragionamento dell\'IA non finisce per allucinare i rilievi?"'}),' Il progetto limita l\'invenzione invece di confidare che il modello si comporti bene. Detect registra solo ci\xf2 che il codice sostiene ("rilevare, non inventare", ',(0,a.jsx)(i.code,{children:"\xa7IV"}),'), verify confronta il codice con il registro e pu\xf2 rispondere "Cannot tell from the code" (',(0,a.jsx)(i.code,{children:"\xa7XV"}),"), i controlli deterministici ancorano i casi decidibili (",(0,a.jsx)(i.code,{children:"\xa7VII"}),") e l'utente \xe8 l'arbitro finale. Questo non rende l'agente infallibile, rende verificabili le sue affermazioni."]}),"\n",(0,a.jsx)(i.p,{children:"Una nota sul posizionamento. SDH \xe8 definita qui indipendentemente dalla sua implementazione di riferimento. Le cinque fasi, il charter formulato in termini di rischio, il riconciliare senza mai solo aggiungere e la sua chiudibilit\xe0, la conoscenza su richiesta, la modalit\xe0 preventiva, il tracciamento dell'identit\xe0 per nome e il confine esclusivamente difensivo sono la metodologia. Un altro team potrebbe implementarli in un altro stack e in un altro ecosistema di agenti, e il risultato sarebbe ancora SDH. Lagune ne \xe8 la prova, non la definizione."}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"xvi-le-insidie-e-come-sdh-le-evita-per-struttura",children:"XVI. Le insidie, e come SDH le evita per struttura"}),"\n",(0,a.jsx)(i.p,{children:"Le metodologie di questa famiglia condividono un insieme noto di modalit\xe0 di fallimento. La risposta di SDH alla maggior parte di esse \xe8 strutturale, incorporata nel flusso invece di essere lasciata alla disciplina."}),"\n",(0,a.jsxs)(i.table,{children:[(0,a.jsx)(i.thead,{children:(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.th,{children:"Insidia"}),(0,a.jsx)(i.th,{children:"Il fallimento"}),(0,a.jsx)(i.th,{children:"La risposta strutturale di SDH"})]})}),(0,a.jsxs)(i.tbody,{children:[(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Specifiche che marciscono, arretrato superato"}),(0,a.jsx)(i.td,{children:"Gli artefatti accumulano voci morte di cui nessuno si fida"}),(0,a.jsxs)(i.td,{children:["Riconciliare senza mai solo aggiungere (",(0,a.jsx)(i.code,{children:"\xa7V"}),"): ogni esecuzione ricontrolla ogni voce e rimuove ci\xf2 che \xe8 risolto"]})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Falsa sicurezza, esito positivo"}),(0,a.jsx)(i.td,{children:"Si presume che un controllo presente chiuda il rischio"}),(0,a.jsxs)(i.td,{children:['Verify confronta il codice con il registro, quindi "Risk not closed" e "Cannot tell" sono verdetti a pieno titolo (',(0,a.jsx)(i.code,{children:"\xa7IV"}),", ",(0,a.jsx)(i.code,{children:"\xa7XV"}),")"]})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Valanga di checklist"}),(0,a.jsx)(i.td,{children:"Le voci generiche nascondono l'unico rischio che conta"}),(0,a.jsxs)(i.td,{children:["Sensibile al contesto pi\xf9 che generico, con il prompt su richiesta che carica solo ci\xf2 che l'ambito richiede (",(0,a.jsx)(i.code,{children:"\xa7VII"}),")"]})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Dipendenza da uno strumento"}),(0,a.jsx)(i.td,{children:"Il metodo \xe8 saldato a un solo fornitore o agente"}),(0,a.jsxs)(i.td,{children:["Veicolo indipendente dall'agente: il valore di sicurezza viene scritto una sola volta, e la sua distribuzione a ogni agente non contiene logica di sicurezza (",(0,a.jsx)(i.code,{children:"\xa7XII"}),")"]})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Il ciclo infinito"}),(0,a.jsx)(i.td,{children:"L'arretrato non si chiude mai, il lavoro non si ferma mai"}),(0,a.jsxs)(i.td,{children:["La chiudibilit\xe0 e lo stato di riposo (",(0,a.jsx)(i.code,{children:"\xa7V"}),")"]})]})]})]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"Tabella 4."})," Le insidie note di questa famiglia di metodologie e la risposta strutturale di SDH a ciascuna."]}),"\n",(0,a.jsx)(i.p,{children:"Il punto \xe8 nominare l'insidia e indicare il meccanismo: non sono inviti alla prudenza, sono propriet\xe0 del flusso."}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"xvii-sviluppi-futuri",children:"XVII. Sviluppi futuri"}),"\n",(0,a.jsx)(i.p,{children:"La metodologia e la sua implementazione di riferimento hanno passi successivi chiari."}),"\n",(0,a.jsxs)(i.ul,{children:["\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"Far crescere il catalogo delle conoscenze:"}),"\nOgni aggiunta mantiene la forma di ",(0,a.jsx)(i.code,{children:"\xa7VII"}),": un file di conoscenza e una riga di catalogo, nessun nuovo comando. La via dal lato dell'utente esiste gi\xe0: l'utente distilla su richiesta le proprie specializzazioni. Pi\xf9 linguaggi, runtime e classi di rischio integrati, ognuno inserito in una categoria, sono la direzione dal lato del maintainer, e ci si aspetta che le specializzazioni evolvano."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"Pi\xf9 controlli deterministici:"}),"\nDove una classe di rischio ha una procedura di decisione netta, una specializzazione pu\xf2 portare con s\xe9 un controllo deterministico che ancora il ragionamento dell'agente a un verdetto ripetibile. Estenderlo a pi\xf9 classi di rischio \xe8 una direzione naturale."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"Valutazione empirica:"}),"\nLa questione aperta pi\xf9 importante \xe8 l'efficacia misurata: la qualit\xe0 delle chiusure e il tasso di verdetti errati su codebase reali. Uno studio sui risultati di sicurezza di SDH \xe8 uno sviluppo futuro, e le affermazioni qui sono limitate di conseguenza."]}),"\n"]}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"xviii-conclusione",children:"XVIII. Conclusione"}),"\n",(0,a.jsx)(i.p,{children:"Lo sviluppo assistito dall'IA ha aperto una lacuna di sicurezza che le checklist generiche non possono colmare, perch\xe9 il rischio che conta \xe8 specifico di ci\xf2 che un sistema fa davvero, e chi lo rilascia potrebbe non sapere cosa chiedere. SDH colma questa lacuna con un flusso sensibile al contesto, esclusivamente difensivo e che si pu\xf2 chiudere, in cui le conoscenze di sicurezza risiedono nella metodologia e nelle sue specializzazioni su richiesta, una base su cui ogni utente pu\xf2 costruire. Rileva il contesto reale del sistema, classifica i rischi che quel contesto comporta, applica le correzioni con attenzione e verifica ognuna, poi archivia ci\xf2 che ha chiuso, cos\xec ogni rilievo raggiunge uno stato finale. La stessa difesa agisce anche in modo preventivo mentre si costruisce il nuovo lavoro, cos\xec ci\xf2 che il flusso chiude resta chiuso. Si adatta a qualsiasi stato di sviluppo in qualsiasi stack, ed estende le conoscenze dello sviluppatore invece di sostituire le persone e gli strumenti che gi\xe0 svolgono quel compito."}),"\n",(0,a.jsx)(i.p,{children:"Lagune \xe8 la prova, ma il contributo \xe8 la convenzione. SDH viene proposta come il flusso di sicurezza essenziale per l'era dello sviluppo con l'IA, perch\xe9 altri la adottino, la affinino e la implementino nei propri stack."}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"riferimenti",children:"Riferimenti"}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"[1]"}),' D. B. Piskala, "Spec-Driven Development: From Code to Contract in the Age of AI Coding Assistants," arXiv preprint arXiv:2602.00180v1 [cs.SE], Jan. 2026. (Submitted to AIWare 2026.) [Online]. Available: ',(0,a.jsx)(i.a,{href:"https://arxiv.org/abs/2602.00180",children:"https://arxiv.org/abs/2602.00180"})]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"[2]"}),' GitHub, "Spec Kit: Toolkit for Spec-Driven Development." [Online]. Available: ',(0,a.jsx)(i.a,{href:"https://github.com/github/spec-kit",children:"https://github.com/github/spec-kit"}),". Accessed: 2026."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"[3]"}),' Fission AI, "OpenSpec: Spec-Driven Development for AI Coding Assistants." [Online]. Available: ',(0,a.jsx)(i.a,{href:"https://github.com/Fission-AI/OpenSpec",children:"https://github.com/Fission-AI/OpenSpec"}),". Accessed: 2026."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"[4]"}),' B. Chess and G. McGraw, "Static Analysis for Security," IEEE Security & Privacy, vol. 2, no. 6, pp. 76-79, 2004, doi: 10.1109/MSP.2004.111.']}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"[5]"}),' OWASP Foundation, "Source Code Analysis Tools." [Online]. Available: ',(0,a.jsx)(i.a,{href:"https://owasp.org/www-community/Source_Code_Analysis_Tools",children:"https://owasp.org/www-community/Source_Code_Analysis_Tools"}),". Accessed: 2026."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"[6]"}),' OWASP Foundation, "OWASP Top 10:2021." [Online]. Available: ',(0,a.jsx)(i.a,{href:"https://owasp.org/Top10/",children:"https://owasp.org/Top10/"}),". Accessed: 2026."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"[7]"}),' MITRE, "Common Weakness Enumeration (CWE)." [Online]. Available: ',(0,a.jsx)(i.a,{href:"https://cwe.mitre.org/",children:"https://cwe.mitre.org/"}),". Accessed: 2026."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"[8]"}),' N. Perry, M. Srivastava, D. Kumar, and D. Boneh, "Do Users Write More Insecure Code with AI Assistants?," in Proc. ACM SIGSAC Conf. on Computer and Communications Security (CCS \'23), 2023, pp. 2785-2799, doi: 10.1145/3576915.3623157. [Online]. Available: ',(0,a.jsx)(i.a,{href:"https://arxiv.org/abs/2211.03622",children:"https://arxiv.org/abs/2211.03622"})]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"[9]"}),' J. Davis and contributors, "safe-regex: Detect Possibly Catastrophic, Exponential-Time Regular Expressions." [Online]. Available: ',(0,a.jsx)(i.a,{href:"https://github.com/davisjam/safe-regex",children:"https://github.com/davisjam/safe-regex"}),". Accessed: 2026."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"[10]"}),' D. Soshnikov, "regexp-tree: Regular Expressions Processor in JavaScript." [Online]. Available: ',(0,a.jsx)(i.a,{href:"https://github.com/DmitrySoshnikov/regexp-tree",children:"https://github.com/DmitrySoshnikov/regexp-tree"}),". Accessed: 2026."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.strong,{children:"[11]"}),' T. Jenkinson, "redos-detector: A CLI and Library to Score How Vulnerable a Regex Pattern Is to ReDoS Attacks." [Online]. Available: ',(0,a.jsx)(i.a,{href:"https://github.com/tjenkinson/redos-detector",children:"https://github.com/tjenkinson/redos-detector"}),". Accessed: 2026."]}),"\n",(0,a.jsx)(i.hr,{}),"\n",(0,a.jsx)(i.h2,{id:"appendice-a-i-principi-alla-lettera",children:"Appendice A: i principi, alla lettera"}),"\n",(0,a.jsxs)(i.ol,{children:["\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"Sicuro per impostazione predefinita, in linguaggio semplice, per tutti allo stesso modo:"}),"\nOgni impostazione predefinita, messaggio e correzione deve essere sicuro fin da subito e comprensibile a qualsiasi utente, sviluppatore o no. Nessuna categoria di utenti \xe8 privilegiata rispetto a un'altra."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"Sensibile al contesto pi\xf9 che generico:"}),"\nOgni fase deve partire dal contesto rilevato in detect e agire su ci\xf2 che il sistema fa davvero. Preferisci raccomandazioni specifiche per quel contesto alle checklist generiche. Le conoscenze di sicurezza risiedono nella specifica e nelle sue specializzazioni su richiesta, ed estendono ci\xf2 che l'utente porta con s\xe9."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"Flessibile pi\xf9 che rigido:"}),"\nSDH si adatta al progetto e all'utente. Principi, requisiti e raccomandazioni sono punti di partenza, non un contratto fisso. Lascia che l'utente riformuli, elimini, aggiunga o restringa qualsiasi cosa. La flessibilit\xe0 non indebolisce mai la base sicura per impostazione predefinita, permette solo all'utente di plasmare il modo in cui viene applicata."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"Riconciliare, mai solo aggiungere:"}),"\nGli artefatti sono documenti vivi, non log. Quando una fase viene rieseguita, riconcilia ogni voce esistente con la verit\xe0 attuale: mantieni ci\xf2 che \xe8 ancora valido, riscrivi ci\xf2 che \xe8 cambiato e rimuovi ci\xf2 che non vale pi\xf9. La chiusura \xe8 questa stessa riconciliazione che arriva alla sua conclusione."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"Solo difesa:"}),"\nSDH verifica, mette in sicurezza e controlla. Non produce mai strumenti offensivi, exploit per uso malevolo o tecniche di elusione del rilevamento per nuocere. I contenuti di sicurezza a doppio uso sono accettabili solo in un contesto chiaramente difensivo e autorizzato."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"Spec-first, guidato da agenti, orientato alla sicurezza:"}),"\nCostruisci il flusso di lavoro a partire da una struttura collaudata: template, comandi, un charter di governo e un agente che esegue le fasi. Reimplementa quella struttura con uno scopo difensivo."]}),"\n"]})]})}function d(e={}){let{wrapper:i}={...(0,r.R)(),...e.components};return i?(0,a.jsx)(i,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}}}]);